    fn answer_with_cards(
        key: QuestionKey,
        ix: usize,
        markdown: MarkdownKey,
        shown: &str,
        open: &OpenFile,
        this: WeakEntity<PromptMode>,
        cx: &mut App,
    ) -> AnyElement {
        use crate::answer_blocks::{AnswerPart, split};
