/// A story as the harness drafts it.
#[derive(Debug, PartialEq, Deserialize)]
struct Drafted {
    #[serde(default)]
    title: String,
    #[serde(default)]
    prompt: String,
    #[serde(default)]
    mode: String,
}

#[derive(Deserialize)]
struct DraftReply {
    stories: Vec<Drafted>,
}

/// The request asking the harness to break `wanted` into stories.
pub fn draft_request(wanted: &str) -> String {
    // Written in system-prompts/planning.pi.
    use crate::baked_prompts::planning;
    format!(
        "{}\n\n{}\n\n{}:\n{wanted}",
        planning::REQUEST,
        planning::REPLY,
        planning::WANTED
    )
}

/// Asks the harness to break `wanted` into stories, as `planning.pi` says,
/// in a run of its own with no session. Blocking.
#[cfg_attr(test, allow(dead_code))]
pub fn ask_for_drafts(project_dir: &Path, wanted: &str) -> Result<String> {
    crate::harness::ask_quickly(project_dir, &draft_request(wanted))
}

/// The stories a drafting reply gives: each's title, prompt, and mode, in
/// order. Chain where its mode isn't one known.
pub fn parse_drafts(reply: &str) -> Result<Vec<(String, String, SendMode)>> {
    let start = reply.find('{').context("the reply held no stories")?;
    let end = reply.rfind('}').context("the reply held no stories")?;
    let parsed: DraftReply = serde_json::from_str(&reply[start..=end])
        .context("the reply's stories couldn't be read")?;
    let stories: Vec<_> = parsed
        .stories
        .into_iter()
        .filter(|story| !story.title.trim().is_empty() || !story.prompt.trim().is_empty())
        .map(|story| {
            let title = if story.title.trim().is_empty() {
                story
                    .prompt
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .trim()
                    .to_string()
            } else {
                story.title.trim().to_string()
            };
            let mode = mode_of_slug(&story.mode).unwrap_or(SendMode::Both);
            (title, story.prompt.trim().to_string(), mode)
        })
        .collect();
    Ok(stories)
}

