pub struct Planning {
    project_dir: PathBuf,
    /// Next sprint, Backlog, and Done, in order.
    sections: [Vec<Story>; 3],
    /// The proposals waiting to be decided, in the order given.
    proposals: Vec<Proposal>,
    open: Option<OpenStory>,
    done_expanded: bool,
    drafting: Option<DraftPanel>,
    editing: Option<ProposalEditor>,
    /// Proposals whose prompts are shown whole.
    read_more: std::collections::HashSet<String>,
    rejected: Vec<Rejected>,
    decided: Vec<Decided>,
    /// Why a proposal couldn't be accepted, by its id.
    refused: std::collections::HashMap<String, String>,
    /// The mode picker open: the story's, and the mode highlighted.
    mode_menu: Option<(String, usize)>,
    /// The story asking to be deleted.
    confirm_delete: Option<String>,
    hooks: PlanningHooks,
    focus: FocusHandle,
    /// Each row's and proposal's focus, by its story's name or its id.
    row_focus: std::collections::HashMap<String, FocusHandle>,
    /// The Done section's toggle's focus.
    done_focus: FocusHandle,
    /// While a row is dragged: the gap it would land in.
    gap: Rc<Cell<Option<(Section, usize)>>>,
    /// Ticks once a second while something runs, for its time.
    _tick: Option<Task<()>>,
}

impl EventEmitter<()> for Planning {}

impl Focusable for Planning {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl Planning {
    pub fn new(project_dir: PathBuf, hooks: PlanningHooks, cx: &mut Context<Self>) -> Self {
        let (sections, proposals) = load(&project_dir);
        let this = Self {
            project_dir,
            sections,
            proposals,
            open: None,
            done_expanded: false,
            drafting: None,
            editing: None,
            read_more: Default::default(),
            rejected: Vec::new(),
            decided: Vec::new(),
            refused: Default::default(),
            mode_menu: None,
            confirm_delete: None,
            hooks,
            focus: cx.focus_handle(),
            row_focus: Default::default(),
            done_focus: cx.focus_handle().tab_stop(true),
            gap: Rc::default(),
            _tick: None,
        };
        this.publish(cx);
        this
    }

    /// The stories of `section`.
    #[cfg(test)]
    pub fn stories(&self, section: Section) -> &[Story] {
        &self.sections[section_ix(section)]
    }

    /// How many stories wait in Next sprint to be sent, for the ribbon.
    pub fn pending(&self) -> SprintPending {
        SprintPending(self.unsent())
    }

    /// Says how many stories wait in Next sprint to be sent, for the ribbon.
    fn publish(&self, cx: &mut App) {
        cx.set_global(self.pending());
    }

    fn unsent(&self) -> usize {
        self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .count()
    }

    fn find(&self, name: &str) -> Option<(Section, usize)> {
        SECTIONS.into_iter().find_map(|section| {
            self.sections[section_ix(section)]
                .iter()
                .position(|story| story.name == name)
                .map(|ix| (section, ix))
        })
    }

    fn story(&self, name: &str) -> Option<&Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get(ix)
    }

    fn story_mut(&mut self, name: &str) -> Option<&mut Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get_mut(ix)
    }

    fn proposal(&self, id: &str) -> Option<&Proposal> {
        self.proposals.iter().find(|proposal| proposal.id == id)
    }

    fn proposal_mut(&mut self, id: &str) -> Option<&mut Proposal> {
        self.proposals.iter_mut().find(|proposal| proposal.id == id)
    }

    /// Saves the order and the proposals in the background.
    fn save_order(&self, cx: &mut Context<Self>) {
        let text = order_of(&self.sections, &self.proposals);
        let dir = self.project_dir.clone();
        cx.background_spawn(async move {
            if let Err(err) = save_order_text(&dir, &text) {
                eprintln!("could not save the plan: {err:#}");
            }
        })
        .detach();
        self.publish(cx);
    }

    /// Saves the story named so in the background.
    fn save_story_named(&self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let (dir, name, source) = (
            self.project_dir.clone(),
            story.name.clone(),
            story.anchor.source(&story.prompt),
        );
        cx.background_spawn(async move {
            if let Err(err) = save_story(&dir, &name, &source) {
                eprintln!("could not save the story: {err:#}");
            }
        })
        .detach();
    }

    /// Adds a story at the end of `section`, open, its title focused, in
    /// the mode last picked.
    pub fn new_story(&mut self, section: Section, window: &mut Window, cx: &mut Context<Self>) {
        self.new_story_at(section, None, window, cx);
    }

    fn new_story_at(
        &mut self,
        section: Section,
        at: Option<usize>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let section = match section {
            Section::Next => Section::Next,
            Section::Backlog | Section::Done => Section::Backlog,
        };
        self.close_story(window, cx);
        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
        let name = story.name.clone();
        let stories = &mut self.sections[section_ix(section)];
        let at = at.unwrap_or(stories.len()).min(stories.len());
        stories.insert(at, story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        self.open_story(&name, window, cx);
    }

    /// Adds a story of `mode` holding `prompt` at the end of `section`.
    pub fn add_story(
        &mut self,
        section: Section,
        title: String,
        prompt: String,
        mode: SendMode,
        cx: &mut Context<Self>,
    ) {
        let story = Story::new(title, prompt, mode, &self.project_dir);
        let name = story.name.clone();
        self.sections[section_ix(section)].push(story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Opens the story named so beneath its row, closing any other. Opened,
    /// it is no longer marked as the agent's.
    fn open_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            return;
        }
        self.close_story(window, cx);
        let Some(story) = self.story_mut(name) else {
            return;
        };
        let marked = story.from_agent || story.updated || story.highlight.is_some();
        story.from_agent = false;
        story.updated = false;
        let highlight = story.highlight.take();
        let (title_text, prompt_text) = (story.title.clone(), story.prompt.clone());
        let title = cx.new(|cx| {
            InputState::new(window, cx)
                .placeholder("Story title")
                .default_value(title_text)
        });
        let prompt = cx.new(|cx| {
            EditorState::new(window, cx)
                .language(piton_syntax::LANGUAGE_NAME)
                .line_number(false)
                .folding(false)
                .soft_wrap(true)
                .scroll_beyond_last_line(Some(0))
                .cursor_surrounding_lines(Some(0))
                .placeholder("Prompt… (the title is sent where there's none)")
                .default_value(prompt_text)
        });
        let completion = cx.new(|cx| CompletionMenu::new(prompt.clone(), window, cx));
        let provider = (self.hooks.completions)(cx);
        completion.update(cx, |menu, cx| menu.set_provider(provider, cx));
        let story_name = name.to_string();
        let subscriptions = vec![
            cx.subscribe_in(&title, window, {
                let name = story_name.clone();
                move |this, input, event: &InputEvent, window, cx| match event {
                    InputEvent::Change => {
                        let value = input.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.title = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                    InputEvent::PressEnter { .. } => this.title_entered(&name, window, cx),
                    _ => {}
                }
            }),
            cx.subscribe_in(&prompt, window, {
                let name = story_name.clone();
                move |this, editor, event: &InputEvent, window, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = editor.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.prompt = value;
                        }
                        this.save_story_named(&name, cx);
                        if let Some(open) = &this.open {
                            open.completion
                                .update(cx, |menu, cx| menu.on_edit(window, cx));
                        }
                    }
                    cx.notify();
                }
            }),
        ];
        title.update(cx, |input, cx| input.focus(window, cx));
        self.open = Some(OpenStory {
            name: story_name,
            title,
            prompt,
            completion,
            fit: GrowToFit::new(PROMPT_MAX_ROWS),
            highlight,
            _subscriptions: subscriptions,
        });
        if marked {
            self.save_order(cx);
        }
        cx.notify();
    }

    /// Closes the open story, its row focused again; one left with neither
    /// title nor prompt is removed.
    fn close_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(open) = self.open.take() else {
            return;
        };
        let empty = self.story(&open.name).is_some_and(|story| {
            story.title.trim().is_empty()
                && story.prompt.trim().is_empty()
                && story.steps().is_empty()
        });
        if empty {
            self.delete(&open.name, cx);
            self.focus.focus(window, cx);
        } else {
            self.focus_row(&open.name, window, cx);
        }
        cx.notify();
    }

    fn toggle_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.close_story(window, cx);
        } else {
            self.open_story(name, window, cx);
        }
    }

    /// Enter in an open story's title: it is kept, and another starts
    /// beneath it, so a list can be written down without the mouse.
    fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        if self.sections[section_ix(section)][ix]
            .title
            .trim()
            .is_empty()
        {
            return;
        }
        self.new_story_at(section, Some(ix + 1), window, cx);
    }

    /// Escape: closes what is open, one layer at a time: the mode picker or
    /// a confirmation, the completions, a proposal being edited, the open
    /// story, then the drafting panel. Whether there was anything to close.
    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if self.mode_menu.take().is_some() || self.confirm_delete.take().is_some() {
            cx.notify();
            return true;
        }
        if let Some(open) = &self.open
            && open.completion.read(cx).is_open()
        {
            open.completion.update(cx, |menu, cx| menu.hide(cx));
            return true;
        }
        if let Some(editor) = self.editing.take() {
            self.focus_row(&editor.id, window, cx);
            return true;
        }
        if self.open.is_some() {
            self.close_story(window, cx);
            return true;
        }
        if self
            .drafting
            .as_ref()
            .is_some_and(|draft| draft.running.is_none())
            && self.proposals.is_empty()
        {
            self.drafting = None;
            self.focus.focus(window, cx);
            cx.notify();
            return true;
        }
        false
    }

    /// Ctrl/Cmd+N: a story in the section of the one open or focused, else
    /// the Backlog.
    fn new_story_here(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let section = self
            .open
            .as_ref()
            .map(|open| open.name.clone())
            .or_else(|| self.focused_row(window))
            .and_then(|name| self.find(&name))
            .map_or(Section::Backlog, |(section, _)| section);
        self.new_story(section, window, cx);
    }

    fn delete(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        self.sections[section_ix(section)].remove(ix);
        self.row_focus.remove(name);
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.open = None;
        }
        if self.confirm_delete.as_deref() == Some(name) {
            self.confirm_delete = None;
        }
        let file = story_file(&self.project_dir, name);
        cx.background_spawn(async move {
            std::fs::remove_file(file).ok();
        })
        .detach();
        self.save_order(cx);
        cx.notify();
    }

    /// Asks, in its row, to delete the story named so.
    fn ask_delete(&mut self, name: &str, cx: &mut Context<Self>) {
        self.mode_menu = None;
        self.confirm_delete = Some(name.to_string());
        cx.notify();
    }

    /// Deletes the story asking to be, the focus going to the row beside.
    fn confirm_delete(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(name) = self.confirm_delete.take() else {
            return;
        };
        let next = self
            .row_after(&name, 1)
            .or_else(|| self.row_after(&name, -1));
        self.delete(&name, cx);
        match next {
            Some(next) => self.focus_row(&next, window, cx),
            None => self.focus.focus(window, cx),
        }
    }

    fn duplicate(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let copy = self.sections[section_ix(section)][ix].duplicate();
        let copy_name = copy.name.clone();
        self.sections[section_ix(section)].insert(ix + 1, copy);
        self.save_story_named(&copy_name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Moves the story named so to place `to` of `section`, counted as the
    /// section is before it is taken out.
    fn move_story(&mut self, name: &str, section: Section, to: usize, cx: &mut Context<Self>) {
        let Some((from_section, from)) = self.find(name) else {
            return;
        };
        let to = if from_section == section && to > from {
            to - 1
        } else {
            to
        };
        let story = self.sections[section_ix(from_section)].remove(from);
        let stories = &mut self.sections[section_ix(section)];
        stories.insert(to.min(stories.len()), story);
        self.save_order(cx);
        cx.notify();
    }

    pub(crate) fn move_to(&mut self, name: &str, section: Section, cx: &mut Context<Self>) {
        let end = self.sections[section_ix(section)].len();
        self.move_story(name, section, end, cx);
    }

    /// Alt+Up or Alt+Down: the story moves one place, and past the end of
    /// its section into the next, between Next sprint and the Backlog, as
    /// dragging does; a story done moves only among its own.
    pub(crate) fn shift_story(&mut self, name: &str, up: bool, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let len = self.sections[section_ix(section)].len();
        match (section, up) {
            (_, true) if ix > 0 => self.move_story(name, section, ix - 1, cx),
            (_, false) if ix + 1 < len => self.move_story(name, section, ix + 2, cx),
            (Section::Backlog, true) => self.move_to(name, Section::Next, cx),
            (Section::Next, false) => self.move_story(name, Section::Backlog, 0, cx),
            _ => {}
        }
    }

    fn set_mode(&mut self, name: &str, mode: SendMode, cx: &mut Context<Self>) {
        if let Ok(mut last) = LAST_MODE.lock() {
            *last = Some(mode);
        }
        if let Some(story) = self.story_mut(name) {
            story.anchor.mode = Some(mode);
        }
        self.mode_menu = None;
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Opens the mode picker of the story named so, its mode highlighted.
    fn open_mode_menu(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let at = SendMode::ALL
            .iter()
            .position(|mode| *mode == story.mode())
            .unwrap_or(0);
        self.confirm_delete = None;
        self.mode_menu = Some((name.to_string(), at));
        cx.notify();
    }

    fn change(
        &mut self,
        name: &str,
        change: impl FnOnce(&mut HiddenAnchor),
        cx: &mut Context<Self>,
    ) {
        if let Some(story) = self.story_mut(name) {
            change(&mut story.anchor);
        }
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Attaches files picked to the story named so.
    fn attach(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let picked = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach".into()),
        });
        let (name, project_dir) = (name.to_string(), self.project_dir.clone());
        cx.spawn_in(window, async move |this, cx| {
            let Ok(Ok(Some(paths))) = picked.await else {
                return;
            };
            let saved = cx
                .background_spawn(async move {
                    let (mut images, mut files) = (Vec::new(), Vec::new());
                    for path in paths {
                        match attached_file::load(&path) {
                            Ok(attached_file::Loaded::Image(image)) => images.push(image),
                            Ok(attached_file::Loaded::File(file)) => files.push(file),
                            Err(_) => {}
                        }
                    }
                    let images = attached_image::save_all(&images, &project_dir)?;
                    let files = attached_file::save_all(&files, &project_dir)?;
                    anyhow::Ok((images, files))
                })
                .await;
            this.update(cx, |this, cx| match saved {
                Ok((images, files)) => this.change(
                    &name,
                    |anchor| {
                        anchor.attached_images.extend(images);
                        anchor.attached_files.extend(files);
                    },
                    cx,
                ),
                Err(err) => eprintln!("could not attach the files: {err:#}"),
            })
            .ok();
        })
        .detach();
    }

    /// How the story stands, once sent, and how long its task has run while
    /// it runs.
    fn status(&self, story: &Story, cx: &App) -> Option<(StoryState, Option<Duration>)> {
        let task = story.task.as_deref()?;
        Some((self.hooks.state)(task, cx).unwrap_or((StoryState::Queued, None)))
    }

    fn state(&self, story: &Story, cx: &App) -> Option<StoryState> {
        self.status(story, cx).map(|(state, _)| state)
    }

    /// Sends the stories named so, in order, as one block, each with its
    /// steps after it.
    fn send_named(&mut self, names: &[String], window: &mut Window, cx: &mut Context<Self>) {
        let mut sends = Vec::new();
        for name in names {
            let project_dir = self.project_dir.clone();
            let Some(story) = self.story_mut(name) else {
                continue;
            };
            if story.text().trim().is_empty() {
                continue;
            }
            let task = crate::prompt_title::name_for(&project_dir, &story.title);
            story.task = Some(task.clone());
            story.from_agent = false;
            sends.push(StorySend {
                name: task,
                text: story.text(),
                mode: story.mode(),
                attached: story.anchor.attached(),
                sliced: story.anchor.sliced,
                model: story.anchor.model.clone(),
                effort: story.anchor.effort.clone(),
                steps: story.steps().to_vec(),
            });
        }
        if sends.is_empty() {
            return;
        }
        self.save_order(cx);
        (self.hooks.send)(sends, window, cx);
        cx.notify();
    }

    /// Sends the story named so alone; a story done is never sent from
    /// here.
    fn send_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .find(name)
            .is_some_and(|(section, _)| section == Section::Done)
        {
            return;
        }
        self.send_named(&[name.to_string()], window, cx);
    }

    /// Sends every story of Next sprint not yet sent, in order, as one
    /// block.
    pub fn send_sprint(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let names: Vec<String> = self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .map(|story| story.name.clone())
            .collect();
        self.send_named(&names, window, cx);
    }

    /// Whether every story of the sprint was sent and has ended.
    fn sprint_ended(&self, cx: &App) -> bool {
        !self.sections[0].is_empty()
            && self.sections[0]
                .iter()
                .all(|story| self.state(story, cx).is_some_and(StoryState::ended))
    }

    /// Closes the sprint: the stories done go to Done; those that failed or
    /// were cancelled stay, to be sent again.
    fn close_sprint(&mut self, cx: &mut Context<Self>) {
        let stories = std::mem::take(&mut self.sections[0]);
        for mut story in stories {
            if self.state(&story, cx) == Some(StoryState::Done) {
                self.sections[2].push(story);
            } else {
                story.task = None;
                self.sections[0].push(story);
            }
        }
        self.save_order(cx);
        cx.notify();
    }

    fn resume(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(task) = self.story(name).and_then(|story| story.task.clone()) {
            (self.hooks.resume)(&task, window, cx);
        }
    }

    // --- Drafting and proposals ---------------------------------------------

    /// Opens the drafting panel beneath the Backlog's heading, or, `about`
    /// a story, beneath it; focused, it takes the request.
    fn open_draft_panel(
        &mut self,
        about: Option<String>,
        focus: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let same = self
            .drafting
            .as_ref()
            .is_some_and(|drafting| drafting.about == about);
        if !same && self.drafting.as_ref().is_none_or(|drafting| drafting.running.is_none()) {
            let placeholder = if about.is_some() {
                "What this story still needs…"
            } else {
                "In a sentence or a paragraph…"
            };
            let input = cx.new(|cx| {
                TextareaState::new(window, cx)
                    .auto_grow(2, DRAFT_MAX_ROWS)
                    .placeholder(placeholder)
            });
            self.drafting = Some(DraftPanel {
                input,
                about,
                running: None,
                activity: Arc::default(),
                cancel: Arc::default(),
                error: None,
                details_open: false,
                proposed_nothing: false,
                _run: None,
            });
        }
        if focus && let Some(drafting) = &self.drafting {
            drafting
                .input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    /// Ask agent: drafting about the story named so.
    fn ask_agent(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        self.open_draft_panel(Some(name.to_string()), true, window, cx);
    }

    /// The stories proposals may add to, by id and title: every one not yet
    /// sent, the one asked about first.
    fn targets(&self, about: Option<&str>) -> Vec<(String, String)> {
        let mut targets: Vec<(String, String)> = self.sections[..2]
            .iter()
            .flatten()
            .filter(|story| story.task.is_none())
            .map(|story| (story.name.clone(), story.title.clone()))
            .collect();
        if let Some(about) = about
            && let Some(at) = targets.iter().position(|(name, _)| name == about)
        {
            let first = targets.remove(at);
            targets.insert(0, first);
        }
        targets
    }

    /// Asks the harness, reading the project and changing nothing, to
    /// propose stories for what the panel's request says.
    fn draft(&mut self, cx: &mut Context<Self>) {
        let Some(drafting) = &self.drafting else {
            return;
        };
        let wanted = drafting.input.read(cx).value().to_string();
        if wanted.trim().is_empty() || drafting.running.is_some() {
            return;
        }
        let about = drafting.about.clone();
        let request = draft_request(
            &wanted,
            &self.targets(about.as_deref()),
            about.as_deref().and_then(|name| self.story(name)),
        );
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        drafting.running = Some(Instant::now());
        drafting.error = None;
        drafting.details_open = false;
        drafting.proposed_nothing = false;
        drafting.cancel = Arc::default();
        *drafting.activity.lock().unwrap() = "Starting the harness…".into();
        let (project_dir, run) = (self.project_dir.clone(), self.hooks.draft);
        let (activity, cancel) = (drafting.activity.clone(), drafting.cancel.clone());
        let task = cx.spawn(async move |this, cx| {
            let reply = cx
                .background_spawn(async move {
                    let tool = Mutex::new(String::new());
                    run(&project_dir, &request, &cancel, &|line| {
                        if let Some(said) = activity(&line, &mut tool.lock().unwrap()) {
                            *activity_of(&activity) = said;
                        }
                    })
                    .map(|reply| parse_proposals(&reply))
                })
                .await;
            this.update(cx, |this, cx| this.drafted(about, reply, cx)).ok();
        });
        if let Some(drafting) = &mut self.drafting {
            drafting._run = Some(task);
        }
        self.keep_ticking(cx);
        cx.notify();
    }

    /// Stops the run, whatever it would have proposed never shown.
    fn stop_draft(&mut self, cx: &mut Context<Self>) {
        if let Some(drafting) = &mut self.drafting {
            drafting.cancel.cancel();
            drafting._run = None;
            drafting.running = None;
        }
        cx.notify();
    }

    fn drafted(
        &mut self,
        about: Option<String>,
        reply: Result<Vec<Proposal>>,
        cx: &mut Context<Self>,
    ) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        drafting.running = None;
        drafting._run = None;
        match reply {
            Ok(proposals) if proposals.is_empty() => drafting.proposed_nothing = true,
            Ok(proposals) => {
                for mut proposal in proposals {
                    proposal.about = about.clone();
                    self.settle_target(&mut proposal);
                    self.proposals.push(proposal);
                }
                self.save_order(cx);
            }
            Err(err) => drafting.error = Some(format!("{err:#}")),
        }
        cx.notify();
    }

    /// A proposal naming a story it can't be added to, one that no longer
    /// exists or was sent, becomes a new story, saying why.
    fn settle_target(&self, proposal: &mut Proposal) {
        let Some(target) = proposal.target.clone() else {
            return;
        };
        let why = match self.story(&target) {
            None => "The story it named no longer exists, so it would be a new story.",
            Some(story) if story.task.is_some() => {
                "The story it named has been sent, so it would be a new story."
            }
            Some(_) => return,
        };
        proposal.target = None;
        proposal.note = Some(why.into());
    }

    /// Takes in a proposal from elsewhere, as an Ask answer's card, to be
    /// edited in the panel before it is accepted.
    pub fn take_proposal(
        &mut self,
        mut proposal: Proposal,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.settle_target(&mut proposal);
        let id = proposal.id.clone();
        if self.proposal(&id).is_none() {
            self.proposals.push(proposal);
            self.save_order(cx);
        }
        self.open_draft_panel(None, false, window, cx);
        self.edit_proposal(&id, window, cx);
    }

    /// Accepts a proposal from elsewhere, as an Ask answer's card does:
    /// recorded in the plan, or, where it can't be, kept in the panel to be
    /// accepted again, and why.
    pub fn accept_outside(
        &mut self,
        mut proposal: Proposal,
        cx: &mut Context<Self>,
    ) -> Result<(), String> {
        self.settle_target(&mut proposal);
        let id = proposal.id.clone();
        if self.proposal(&id).is_none() {
            self.proposals.push(proposal);
        }
        self.accept(&id, cx).map(|_| ())
    }

    /// Accepts the proposal `id` into the plan, saved straight away: a new
    /// story at the Backlog's end, marked "From agent", or a step at the end
    /// of the story it names, which is marked "Updated by agent". Where that
    /// story no longer exists, or was sent, nothing is added: the proposal
    /// stays, made a new story, saying why. Gives the story it went to.
    pub(crate) fn accept(&mut self, id: &str, cx: &mut Context<Self>) -> Result<String, String> {
        let Some(proposal) = self.proposal(id).cloned() else {
            return Err("That proposal was already decided.".into());
        };
        let (story, note) = match &proposal.target {
            None => {
                let mut story = Story::new(
                    proposal.story_title(),
                    proposal.prompt.clone(),
                    proposal.mode(),
                    &self.project_dir,
                );
                story.from_agent = true;
                let name = story.name.clone();
                self.sections[1].push(story);
                self.save_story_named(&name, cx);
                (name, "Added to Backlog".to_string())
            }
            Some(target) => {
                let why = match self.story(target) {
                    None => Some("That story no longer exists, so the step wasn't added."),
                    Some(story) if story.task.is_some() => {
                        Some("That story has been sent, so the step wasn't added.")
                    }
                    Some(_) => None,
                };
                if let Some(why) = why {
                    if let Some(kept) = self.proposal_mut(id) {
                        kept.target = None;
                        kept.note = Some("It would now be a new story.".into());
                    }
                    self.refused.insert(id.to_string(), why.into());
                    self.save_order(cx);
                    cx.notify();
                    return Err(why.into());
                }
                let story = self.story_mut(target).expect("found just now");
                let mode = match (proposal.mode(), story.mode()) {
                    (SendMode::Spec, _) => SendMode::Spec,
                    (SendMode::Code, _) => SendMode::Code,
                    (_, SendMode::Spec) => SendMode::Spec,
                    _ => SendMode::Code,
                };
                story.anchor.added_steps.push(AddedStep {
                    mode,
                    prompt: proposal.prompt.clone(),
                    model: story.anchor.model.clone(),
                    effort: story.anchor.effort.clone(),
                });
                story.updated = true;
                story.highlight = Some(story.anchor.added_steps.len() - 1);
                let note = format!("Added to {}", story.title);
                let name = story.name.clone();
                self.save_story_named(&name, cx);
                (name, note)
            }
        };
        self.proposals.retain(|proposal| proposal.id != id);
        self.refused.remove(id);
        if self.editing.as_ref().is_some_and(|editor| editor.id == id) {
            self.editing = None;
        }
        self.decided.push(Decided {
            text: note,
            story: story.clone(),
        });
        self.save_order(cx);
        self.close_panel_when_decided(cx);
        cx.notify();
        Ok(story)
    }

    /// Rejects the proposal `id`: its card goes, an Undo in its place for a
    /// few seconds.
    pub(crate) fn reject(&mut self, id: &str, cx: &mut Context<Self>) {
        let Some(at) = self.proposals.iter().position(|proposal| proposal.id == id) else {
            return;
        };
        let proposal = self.proposals.remove(at);
        if self.editing.as_ref().is_some_and(|editor| editor.id == id) {
            self.editing = None;
        }
        self.rejected.push(Rejected {
            proposal,
            at,
            when: Instant::now(),
        });
        self.save_order(cx);
        cx.spawn(async move |this, cx| {
            cx.background_executor().timer(UNDO_FOR).await;
            this.update(cx, |this, cx| {
                this.rejected.retain(|rejected| rejected.when.elapsed() < UNDO_FOR);
                this.close_panel_when_decided(cx);
                cx.notify();
            })
            .ok();
        })
        .detach();
        cx.notify();
    }

    /// Brings back the proposal `id`, rejected moments ago, where it was.
    fn undo_reject(&mut self, id: &str, cx: &mut Context<Self>) {
        let Some(at) = self
            .rejected
            .iter()
            .position(|rejected| rejected.proposal.id == id)
        else {
            return;
        };
        let rejected = self.rejected.remove(at);
        let place = rejected.at.min(self.proposals.len());
        self.proposals.insert(place, rejected.proposal);
        self.save_order(cx);
        cx.notify();
    }

    fn accept_all(&mut self, cx: &mut Context<Self>) {
        let ids: Vec<String> = self.proposals.iter().map(|proposal| proposal.id.clone()).collect();
        for id in ids {
            self.accept(&id, cx).ok();
        }
    }

    fn reject_all(&mut self, cx: &mut Context<Self>) {
        let ids: Vec<String> = self.proposals.iter().map(|proposal| proposal.id.clone()).collect();
        for id in ids {
            self.reject(&id, cx);
        }
    }

    /// The panel closes itself once no proposal is left to decide, nor any
    /// rejected one waiting on its Undo.
    fn close_panel_when_decided(&mut self, cx: &mut Context<Self>) {
        let running = self
            .drafting
            .as_ref()
            .is_some_and(|drafting| drafting.running.is_some());
        if self.proposals.is_empty() && self.rejected.is_empty() && !running {
            self.drafting = None;
            self.editing = None;
            self.decided.clear();
            cx.notify();
        }
    }

    /// Opens the proposal `id` for editing in its card: its title, prompt,
    /// mode, and target, changed before it is accepted.
    pub(crate) fn edit_proposal(&mut self, id: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some(proposal) = self.proposal(id).cloned() else {
            return;
        };
        let title = cx.new(|cx| {
            InputState::new(window, cx)
                .placeholder("Story title")
                .default_value(proposal.title.clone())
        });
        let prompt = cx.new(|cx| {
            TextareaState::new(window, cx)
                .auto_grow(2, PROMPT_MAX_ROWS)
                .default_value(proposal.prompt.clone())
        });
        let subscriptions = vec![
            cx.subscribe_in(&title, window, {
                let id = id.to_string();
                move |this, input, event: &InputEvent, _, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = input.read(cx).value().to_string();
                        if let Some(proposal) = this.proposal_mut(&id) {
                            proposal.title = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                }
            }),
            cx.subscribe_in(&prompt, window, {
                let id = id.to_string();
                move |this, input, event: &InputEvent, _, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = input.read(cx).value().to_string();
                        if let Some(proposal) = this.proposal_mut(&id) {
                            proposal.prompt = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                }
            }),
        ];
        title.update(cx, |input, cx| input.focus(window, cx));
        self.editing = Some(ProposalEditor {
            id: id.to_string(),
            title,
            prompt,
            _subscriptions: subscriptions,
        });
        cx.notify();
    }

    fn set_proposal(
        &mut self,
        id: &str,
        change: impl FnOnce(&mut Proposal),
        cx: &mut Context<Self>,
    ) {
        if let Some(proposal) = self.proposal_mut(id) {
            change(proposal);
            proposal.note = None;
        }
        self.refused.remove(id);
        self.save_order(cx);
        cx.notify();
    }

    // --- Rows and the keyboard ----------------------------------------------

    /// The rows in the order they are shown, by their stories' names and
    /// proposals' ids.
    fn shown_rows(&self) -> Vec<String> {
        let ids: Vec<String> = self
            .proposals
            .iter()
            .map(|proposal| proposal.id.clone())
            .collect();
        let about = self.panel_about();
        let mut rows = Vec::new();
        for section in SECTIONS {
            if section == Section::Done && !self.done_expanded {
                continue;
            }
            if section == Section::Backlog && about.is_none() {
                rows.extend(ids.iter().cloned());
            }
            for story in &self.sections[section_ix(section)] {
                rows.push(story.name.clone());
                if about.as_deref() == Some(story.name.as_str()) {
                    rows.extend(ids.iter().cloned());
                }
            }
        }
        rows
    }

    /// The story the panel shows beneath, while it shows beneath one.
    fn panel_about(&self) -> Option<String> {
        let about = match &self.drafting {
            Some(drafting) => drafting.about.clone(),
            None => self.proposals.first().and_then(|proposal| proposal.about.clone()),
        }?;
        self.find(&about).is_some().then_some(about)
    }

    /// The row `step` rows on from the one named so.
    fn row_after(&self, name: &str, step: isize) -> Option<String> {
        let rows = self.shown_rows();
        let at = rows.iter().position(|row| row == name)? as isize + step;
        rows.get(usize::try_from(at).ok()?).cloned()
    }

    fn row_focus(&mut self, name: &str, cx: &mut App) -> FocusHandle {
        self.row_focus
            .entry(name.to_string())
            .or_insert_with(|| cx.focus_handle().tab_stop(true))
            .clone()
    }

    fn focus_row(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let handle = self.row_focus(name, cx);
        handle.focus(window, cx);
        cx.notify();
    }

    /// The story or proposal whose row has the focus.
    fn focused_row(&self, window: &Window) -> Option<String> {
        self.row_focus
            .iter()
            .find(|(_, handle)| handle.is_focused(window))
            .map(|(name, _)| name.clone())
    }

    /// Up or Down on a focused row: the mode picker's highlight moves while
    /// it is open, else the focus moves to the row beside.
    fn step_rows(&mut self, step: isize, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((_, at)) = &mut self.mode_menu {
            let count = SendMode::ALL.len() as isize;
            *at = (*at as isize + step).rem_euclid(count) as usize;
            cx.notify();
            return;
        }
        let Some(name) = self.focused_row(window) else {
            return;
        };
        if let Some(next) = self.row_after(&name, step) {
            self.focus_row(&next, window, cx);
        }
    }

    /// Enter on a focused row: picks the highlighted mode while the picker
    /// is open, deletes a story whose delete was asked for, else opens or
    /// closes the story.
    fn enter_row(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((name, at)) = self.mode_menu.clone() {
            self.set_mode(&name, SendMode::ALL[at], cx);
            return;
        }
        if self.confirm_delete.is_some() {
            return self.confirm_delete(window, cx);
        }
        if let Some(name) = self.focused_row(window) {
            self.toggle_story(&name, window, cx);
        }
    }

    /// The focus after a proposal is decided: the next row, else the one
    /// before, else Planning.
    fn focus_after_decision(&mut self, id: &str, window: &mut Window, cx: &mut Context<Self>) {
        let next = self.row_after(id, 1).or_else(|| self.row_after(id, -1));
        match next {
            Some(next) if next != id => self.focus_row(&next, window, cx),
            _ => self.focus.focus(window, cx),
        }
    }

    /// Ticks once a second while something runs, so its time counts.
    fn keep_ticking(&mut self, cx: &mut Context<Self>) {
        if self._tick.is_some() {
            return;
        }
        self._tick = Some(cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(Duration::from_secs(1))
                    .await;
                let running = this
                    .update(cx, |this, cx| {
                        let running = this.any_running(cx)
                            || this
                                .drafting
                                .as_ref()
                                .is_some_and(|drafting| drafting.running.is_some());
                        if running {
                            cx.notify();
                        } else {
                            this._tick = None;
                        }
                        running
                    })
                    .unwrap_or(false);
                if !running {
                    break;
                }
            }
        }));
    }

    fn any_running(&self, cx: &App) -> bool {
        self.sections
            .iter()
            .flatten()
            .any(|story| self.state(story, cx) == Some(StoryState::Running))
    }
}

/// The live line's text, however its lock was left.
fn activity_of(activity: &Mutex<String>) -> std::sync::MutexGuard<'_, String> {
    activity.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Every section, in the order they are shown.
const SECTIONS: [Section; 3] = [Section::Next, Section::Backlog, Section::Done];

fn section_ix(section: Section) -> usize {
    match section {
        Section::Next => 0,
        Section::Backlog => 1,
        Section::Done => 2,
    }
}

/// How wide a row's grip is.
const GRIP_WIDTH: Pixels = px(16.);

/// How wide a row's mode pill is.
const PILL_WIDTH: Pixels = px(72.);

/// How wide a row's status and time are.
const STATUS_WIDTH: Pixels = px(96.);

/// How tall a section's heading is.
const HEADING_HEIGHT: Pixels = px(32.);

/// How far apart rows are.
const ROW_GAP: Pixels = px(2.);

/// How far a section's first row is beneath its heading.
const HEADING_GAP: Pixels = px(8.);

/// A mode's pill: its label, small, in its colour.
fn mode_pill_label(mode: SendMode, cx: &App) -> Div {
    let color = chat_input::mode_color(mode, cx);
    div()
        .flex_none()
        .px_1p5()
        .rounded(px(4.))
        .text_xs()
        .font_medium()
        .text_color(color)
        .bg(color.opacity(0.14))
        .child(mode_label(mode))
}

/// A sent story's status, as a task's is shown in the message list: its
/// coloured label, with a spinner and its time while it runs, and a pause
/// icon while paused.
fn status_label(state: StoryState, elapsed: Option<Duration>, cx: &App) -> AnyElement {
    use crate::theme::Hue;
    let hue = match state {
        StoryState::Queued => Hue::Grey,
        StoryState::Running => Hue::Amber,
        StoryState::Done => Hue::Green,
        StoryState::Failed => Hue::Red,
        StoryState::Cancelled => Hue::Orange,
        // The theme's warning colour, as a paused task's.
        StoryState::Paused => Hue::Amber,
    };
    let muted = cx.theme().muted_foreground;
    let tag = crate::theme::tag(hue, cx).text_xs().child(
        h_flex()
            .gap_1()
            .items_center()
            .when(state == StoryState::Paused, |tag| {
                tag.child(Icon::new(IconName::Pause).xsmall())
            })
            .child(state.label()),
    );
    h_flex()
        .gap_1()
        .justify_end()
        .items_center()
        .when(state == StoryState::Running, |row| {
            row.child(Spinner::new().xsmall())
        })
        .child(tag)
        .children(
            elapsed
                .filter(|_| state == StoryState::Running)
                .map(|elapsed| {
                    div()
                        .text_xs()
                        .text_color(muted)
                        .font_features(crate::subagents::tabular_figures())
                        .child(crate::subagents::format_elapsed(elapsed))
                }),
        )
        .into_any_element()
}

/// `element`, taking the clicks on what it holds for itself, so the row
/// it sits in never sees them.
fn own_clicks(element: Div) -> Div {
    element.on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
}

/// An empty state: one muted line, centred, saying what is missing and what
/// to do.
fn empty_line(text: String, muted: Hsla) -> Div {
    div()
        .w_full()
        .h(ROW_HEIGHT)
        .flex()
        .items_center()
        .justify_center()
        .text_sm()
        .text_color(muted)
        .child(text)
}

/// A loading state: a spinner and a short muted label, where the result
/// will appear.
fn loading_line(label: String, muted: Hsla) -> Div {
    h_flex()
        .h(ROW_HEIGHT)
        .px_3()
        .gap_2()
        .items_center()
        .min_w_0()
        .text_sm()
        .text_color(muted)
        .child(Spinner::new().xsmall())
        .child(div().min_w_0().truncate().child(label))
}

/// `text` cut to its first `lines` lines, and whether anything was cut.
fn clipped(text: &str, lines: usize) -> (String, bool) {
    let all: Vec<&str> = text.lines().collect();
    if all.len() <= lines {
        return (text.to_string(), false);
    }
    (format!("{}…", all[..lines].join("\n")), true)
}

impl Planning {
    fn render_heading(&self, section: Section, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let count = self.sections[section_ix(section)].len();
        let paused = self.sections[section_ix(section)]
            .iter()
            .filter(|story| self.state(story, cx) == Some(StoryState::Paused))
            .count();
        let warning = crate::theme::Hue::Amber.of(crate::theme::palette(cx));
        let mut actions: Vec<AnyElement> = Vec::new();
        match section {
            Section::Next => {
                if self.sprint_ended(cx) {
                    actions.push(
                        Button::new("planning-close-sprint")
                            .ghost()
                            .small()
                            .label("Close sprint")
                            .tooltip(
                                "Move the stories done to Done, leaving any that failed to send again",
                            )
                            .on_click(cx.listener(|this, _, _, cx| this.close_sprint(cx)))
                            .into_any_element(),
                    );
                }
                let unsent = self.unsent();
                actions.push(
                    Button::new("planning-send-sprint")
                        .primary()
                        .small()
                        .icon(IconName::Send)
                        .label("Send sprint")
                        .disabled(unsent == 0)
                        .tooltip(match unsent {
                            0 => "Nothing in Next sprint is waiting to be sent".to_string(),
                            1 => format!("Send the one story waiting ({MOD}Shift+Enter)"),
                            n => format!(
                                "Send the {n} stories waiting, in order ({MOD}Shift+Enter)"
                            ),
                        })
                        .on_click(
                            cx.listener(|this, _, window, cx| this.send_sprint(window, cx)),
                        )
                        .into_any_element(),
                );
            }
            Section::Backlog => {
                actions.push(
                    Button::new("planning-draft-stories")
                        .ghost()
                        .small()
                        .icon(IconName::Sparkles)
                        .label("Draft stories")
                        .tooltip("Describe what you want, and have the agent propose stories")
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.open_draft_panel(None, true, window, cx)
                        }))
                        .into_any_element(),
                );
            }
            Section::Done => {}
        }
        let name = div().text_sm().font_semibold().child(section.label());
        let heading = if section == Section::Done {
            // Collapsed until opened, from its heading.
            gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-done-toggle")
                    .track_focus(&self.done_focus)
                    .gap_2()
                    .px_1()
                    .items_center()
                    .rounded(theme.radius)
                    .border_1()
                    .border_color(gpui_kit::transparent_black())
                    .focus(|toggle| toggle.border_color(theme.ring))
                    .cursor_pointer()
                    .text_color(muted)
                    .aria_label(if self.done_expanded {
                        "Hide the stories done"
                    } else {
                        "Show the stories done"
                    })
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .on_action(cx.listener(|this, _: &ToggleStory, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .key_context(ROW_CONTEXT)
                    .child(
                        Icon::new(if self.done_expanded {
                            IconName::ChevronDown
                        } else {
                            IconName::ChevronRight
                        })
                        .xsmall(),
                    )
                    .child(name),
            )
            .into_any_element()
        } else {
            name.into_any_element()
        };
        h_flex()
            .w_full()
            .h(HEADING_HEIGHT)
            .flex_none()
            .gap_2()
            .items_center()
            .child(heading)
            .child(div().text_xs().text_color(muted).child(count.to_string()))
            .when(paused > 0, |row| {
                row.child(
                    div()
                        .text_xs()
                        .text_color(warning)
                        .child(format!("{paused} paused")),
                )
            })
            .child(div().flex_1())
            .children(actions)
            .into_any_element()
    }

    fn render_section(
        &mut self,
        section: Section,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let heading = self.render_heading(section, cx);
        let mut column = v_flex()
            .w_full()
            .gap(ROW_GAP)
            .child(div().pb(HEADING_GAP - ROW_GAP).child(heading));
        let about = self.panel_about();
        let panel_wanted = self.drafting.is_some() || !self.proposals.is_empty();
        if section == Section::Backlog && panel_wanted && about.is_none() {
            // Proposals kept from before come back in their panel.
            if self.drafting.is_none() {
                self.open_draft_panel(None, false, window, cx);
            }
            column = column.child(self.render_draft_panel(window, cx));
        }
        if section == Section::Done && !self.done_expanded {
            return column.into_any_element();
        }
        let gap = self.gap.get();
        let count = self.sections[section_ix(section)].len();
        if count == 0 {
            // Lets UI tests find the empty state; inert in normal builds.
            column = column.child(gpui_kit::TestSupportExt::test_support(
                self.drop_zone(
                    section,
                    0,
                    div().id(SharedString::from(format!(
                        "planning-empty-{}",
                        section.key()
                    ))),
                    cx,
                )
                .child(empty_line(section.empty(), muted)),
            ));
        }
        for ix in 0..count {
            let name = self.sections[section_ix(section)][ix].name.clone();
            let open = self.open.as_ref().is_some_and(|open| open.name == name);
            let row = self.render_row(section, ix, open, gap, window, cx);
            column = column.child(row);
            if open {
                column = column.child(self.render_open(&name, window, cx));
            }
            if panel_wanted && about.as_deref() == Some(name.as_str()) {
                if self.drafting.is_none() {
                    self.open_draft_panel(Some(name.clone()), false, window, cx);
                }
                column = column.child(self.render_draft_panel(window, cx));
            }
        }
        if section != Section::Done {
            let new_story = self
                .drop_zone(
                    section,
                    count,
                    h_flex()
                        .id(SharedString::from(format!(
                            "planning-new-story-{}",
                            section.key()
                        )))
                        .h(px(28.))
                        .px_3()
                        .gap_2()
                        .items_center()
                        .rounded(theme.radius)
                        .cursor_pointer()
                        .text_sm()
                        .text_color(muted)
                        .aria_label("New story")
                        .tooltip(move |window, cx| {
                            gpui_kit::component::tooltip::Tooltip::new(format!(
                                "Add a story here ({MOD}N)"
                            ))
                            .build(window, cx)
                        })
                        .hover(|row| row.bg(theme.list_hover)),
                    cx,
                )
                .on_click(
                    cx.listener(move |this, _, window, cx| this.new_story(section, window, cx)),
                )
                .child(Icon::new(IconName::Plus).xsmall())
                .child("New story");
            column = column.child(gpui_kit::TestSupportExt::test_support(new_story));
        }
        column.into_any_element()
    }

    /// `element` as somewhere a dragged story can be dropped, at place `at`
    /// of `section`.
    fn drop_zone(
        &self,
        section: Section,
        at: usize,
        element: Stateful<Div>,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let gap = self.gap.clone();
        let shown = gap.get() == Some((section, at));
        element
            .relative()
            .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
                if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at))
                {
                    gap.set(Some((section, at)));
                    window.refresh();
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                this.gap.set(None);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(shown, |this| {
                this.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
    }

    fn render_mode_menu(
        &self,
        name: &str,
        mode: SendMode,
        highlighted: usize,
        cx: &mut Context<Self>,
    ) -> impl IntoElement + use<> {
        let theme = cx.theme().clone();
        let items = SendMode::ALL
            .into_iter()
            .enumerate()
            .map(|(at, choice)| {
                let name = name.to_string();
                h_flex()
                    .id(SharedString::from(format!(
                        "planning-mode-{name}-{}",
                        mode_label(choice)
                    )))
                    .px_2()
                    .h(px(26.))
                    .gap_2()
                    .items_center()
                    .rounded(theme.radius)
                    .cursor_pointer()
                    .when(at == highlighted, |item| item.bg(theme.list_active))
                    .hover(|item| item.bg(theme.list_hover))
                    .aria_label(mode_label(choice))
                    .on_click(cx.listener(move |this, _, _, cx| this.set_mode(&name, choice, cx)))
                    .child(div().w(px(14.)).children(
                        (choice == mode).then(|| Icon::new(IconName::Check).xsmall()),
                    ))
                    .child(mode_pill_label(choice, cx))
            })
            .collect::<Vec<_>>();
        let menu = v_flex()
            .id(SharedString::from(format!("planning-mode-menu-{name}")))
            .mt(px(26.))
            .w(px(140.))
            .p_1()
            .rounded(theme.radius)
            .border_1()
            .border_color(theme.border)
            .bg(theme.popover)
            .shadow_md()
            .occlude()
            .on_mouse_down_out(cx.listener(|this, _, _, cx| {
                this.mode_menu = None;
                cx.notify();
            }))
            .children(items);
        deferred(
            anchored()
                .snap_to_window()
                .child(gpui_kit::TestSupportExt::test_support(menu)),
        )
        .with_priority(2)
    }

    fn render_row(
        &mut self,
        section: Section,
        ix: usize,
        open: bool,
        gap: Option<(Section, usize)>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let story = &self.sections[section_ix(section)][ix];
        let name = story.name.clone();
        let mode = story.mode();
        let status = self.status(story, cx);
        let (from_agent, updated, attached) =
            (story.from_agent, story.updated, story.has_attachments());
        let steps: Vec<String> = story
            .steps()
            .iter()
            .enumerate()
            .map(|(at, step)| {
                format!(
                    "{}. {}",
                    at + 2,
                    step.prompt.lines().next().unwrap_or_default()
                )
            })
            .collect();
        let task = story.task.clone();
        let untitled = story.title.trim().is_empty();
        let title: SharedString = if untitled {
            "Untitled".into()
        } else {
            story.title.clone().into()
        };
        let len = self.sections[section_ix(section)].len();
        let focus = self.row_focus(&name, cx);
        let focused = focus.is_focused(window);
        let group = SharedString::from(format!("planning-row-{name}"));
        let paused = status.is_some_and(|(state, _)| state == StoryState::Paused);
        let confirming = self.confirm_delete.as_deref() == Some(name.as_str());

        // The mode picker: its pill, and beneath it, while open, the modes.
        let mode_menu = self
            .mode_menu
            .as_ref()
            .filter(|(of, _)| *of == name)
            .map(|(_, at)| *at)
            .map(|highlighted| self.render_mode_menu(&name, mode, highlighted, cx));
        let mode_picker = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-mode-{name}")))
                .ghost()
                .xsmall()
                .child(mode_pill_label(mode, cx))
                .tooltip("How it will be sent (M)")
                .on_click(cx.listener(move |this, _, _, cx| {
                    if this.mode_menu.as_ref().is_some_and(|(of, _)| *of == name) {
                        this.mode_menu = None;
                        cx.notify();
                    } else {
                        this.open_mode_menu(&name, cx);
                    }
                }))
        };
        let send = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-send-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Send)
                .label("Send")
                .tooltip(format!("Send this story on its own ({MOD}Enter)"))
                .on_click(
                    cx.listener(move |this, _, window, cx| this.send_story(&name, window, cx)),
                )
        };
        let resume = paused.then(|| {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-resume-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Play)
                .label("Resume")
                .tooltip("Resume this story's task where it left off")
                .on_click(cx.listener(move |this, _, window, cx| this.resume(&name, window, cx)))
        });
        let this = cx.entity().downgrade();
        let menu_name = name.clone();
        let sent = task.is_some();
        let menu = Button::new(SharedString::from(format!("planning-menu-{name}")))
            .ghost()
            .xsmall()
            .icon(IconName::Ellipsis)
            .tooltip("More")
            .dropdown_menu_with_anchor(gpui_kit::Anchor::TopRight, move |menu, window, _| {
                let _ = window;
                let item = |label: &'static str,
                            act: fn(&mut Planning, &str, &mut Window, &mut Context<Planning>)| {
                    let (this, name) = (this.clone(), menu_name.clone());
                    PopupMenuItem::new(label).on_click(move |_, window, cx| {
                        this.update(cx, |this, cx| act(this, &name, window, cx)).ok();
                    })
                };
                let menu = match section {
                    Section::Next => menu.item(item("Move to backlog", |this, name, _, cx| {
                        this.move_story(name, Section::Backlog, 0, cx)
                    })),
                    Section::Backlog | Section::Done => {
                        menu.item(item("Move to next sprint", |this, name, _, cx| {
                            this.move_to(name, Section::Next, cx)
                        }))
                    }
                };
                let menu = if sent {
                    menu
                } else {
                    menu.item(item("Ask agent", |this, name, window, cx| {
                        this.ask_agent(name, window, cx)
                    }))
                };
                menu.item(item("Duplicate", |this, name, _, cx| this.duplicate(name, cx)))
                    .separator()
                    .item(item("Delete…", |this, name, _, cx| this.ask_delete(name, cx)))
            });
        let confirm = confirming.then(|| {
            h_flex()
                .gap_1()
                .items_center()
                .child(
                    div()
                        .text_xs()
                        .text_color(theme.danger)
                        .child("Delete this story?"),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-delete-{name}")))
                        .danger()
                        .xsmall()
                        .label("Delete")
                        .tooltip("Delete it for good (Enter)")
                        .on_click(
                            cx.listener(|this, _, window, cx| this.confirm_delete(window, cx)),
                        ),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-keep-{name}")))
                        .ghost()
                        .xsmall()
                        .label("Cancel")
                        .tooltip("Keep it (Escape)")
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.confirm_delete = None;
                            cx.notify();
                        })),
                )
        });

        let dragging = cx.has_active_drag();
        let drag = StoryDrag {
            name: name.clone(),
            title: title.clone(),
            mode,
        };
        let click_name = name.clone();
        let steps_tip: SharedString = steps.join("\n").into();
        let step_count = steps.len();
        let row = h_flex()
            .id(SharedString::from(format!("planning-story-{name}")))
            .key_context(ROW_CONTEXT)
            .track_focus(&focus)
            .aria_label(title.clone())
            .group(group.clone())
            .relative()
            .w_full()
            .h(ROW_HEIGHT)
            .flex_none()
            .px_3()
            .gap_2()
            .items_center()
            .rounded(theme.radius)
            // The focus ring, on the row the keys work on.
            .border_1()
            .border_color(if focused {
                theme.ring
            } else {
                gpui_kit::transparent_black()
            })
            .cursor_pointer()
            .when(open, |row| row.bg(theme.list_active))
            .when(!open, |row| row.hover(|row| row.bg(theme.list_hover)))
            .on_click(cx.listener(move |this, _, window, cx| {
                // A story sent opens its task; any other opens, or closes.
                this.focus_row(&click_name, window, cx);
                if let Some(task) = task.as_deref().filter(|_| !open) {
                    (this.hooks.open_task)(task, window, cx);
                } else {
                    this.toggle_story(&click_name, window, cx);
                }
            }))
            .on_action(
                cx.listener(|this, _: &PreviousRow, window, cx| this.step_rows(-1, window, cx)),
            )
            .on_action(cx.listener(|this, _: &NextRow, window, cx| this.step_rows(1, window, cx)))
            .on_action(cx.listener(|this, _: &ToggleStory, window, cx| this.enter_row(window, cx)))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryUp, window, cx| {
                    this.shift_story(&name, true, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryDown, window, cx| {
                    this.shift_story(&name, false, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &SendStory, window, cx| this.send_story(&name, window, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &PickMode, _, cx| this.open_mode_menu(&name, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &DeleteStory, _, cx| this.ask_delete(&name, cx)
            }))
            .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
            .on_drag_move({
                let gap = self.gap.clone();
                move |event: &DragMoveEvent<StoryDrag>, window, _| {
                    let bounds = event.bounds;
                    if !bounds.contains(&event.event.position) {
                        return;
                    }
                    let at = ix + (event.event.position.y > bounds.center().y) as usize;
                    if gap.get() != Some((section, at)) {
                        gap.set(Some((section, at)));
                        window.refresh();
                    }
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                let at = this.gap.take().map_or(ix, |(_, at)| at);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(dragging && gap == Some((section, ix)), |row| {
                row.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
            .when(
                dragging && gap == Some((section, ix + 1)) && ix + 1 == len,
                |row| row.child(crate::prompt_mode::drop_indicator(false, true, cx)),
            )
            // The grip, in its column.
            .child(
                own_clicks(div().w(GRIP_WIDTH).flex_none().flex().justify_center()).child(
                    Icon::new(IconName::GripVertical)
                        .xsmall()
                        .text_color(muted)
                        .cursor_grab(),
                ),
            )
            // The mode pill, in its column, taking its own clicks.
            .child(
                own_clicks(div().relative().w(PILL_WIDTH).flex_none())
                    .child(mode_picker)
                    .children(mode_menu),
            )
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap_2()
                    .items_center()
                    // From the agent, until it is first opened.
                    .when(from_agent, |title| {
                        title.child(
                            div()
                                .id(SharedString::from(format!("planning-from-agent-{name}")))
                                .flex_none()
                                .tooltip(|window, cx| {
                                    gpui_kit::component::tooltip::Tooltip::new("From agent")
                                        .build(window, cx)
                                })
                                .child(
                                    Icon::new(IconName::Sparkles)
                                        .xsmall()
                                        .text_color(theme.primary),
                                ),
                        )
                    })
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .text_color(if untitled { muted } else { theme.foreground })
                            .child(title),
                    )
                    .when(updated, |title| {
                        title.child(
                            div()
                                .flex_none()
                                .text_xs()
                                .text_color(theme.primary)
                                .child("Updated by agent"),
                        )
                    })
                    .when(step_count > 0, |title| {
                        title.child(
                            div()
                                .id(SharedString::from(format!("planning-steps-{name}")))
                                .flex_none()
                                .text_xs()
                                .text_color(muted)
                                .tooltip(move |window, cx| {
                                    gpui_kit::component::tooltip::Tooltip::new(steps_tip.clone())
                                        .build(window, cx)
                                })
                                .child(if step_count == 1 {
                                    "2 steps".to_string()
                                } else {
                                    format!("{} steps", step_count + 1)
                                }),
                        )
                    })
                    .when(attached, |title| {
                        title.child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                    }),
            )
            // The status and time, right-aligned in a column of their own;
            // nothing for a story not yet sent.
            .child(
                div()
                    .w(STATUS_WIDTH)
                    .flex_none()
                    .flex()
                    .justify_end()
                    .children(status.map(|(state, elapsed)| status_label(state, elapsed, cx))),
            )
            .children(confirm.map(|confirm| own_clicks(div().flex_none()).child(confirm)))
            .children(resume.map(|resume| own_clicks(div().flex_none()).child(resume)))
            .when(!confirming, |row| {
                row.child(
                    own_clicks(h_flex())
                        .flex_none()
                        .gap_0p5()
                        .when(!focused, |buttons| {
                            buttons.invisible().group_hover(group, |this| this.visible())
                        })
                        .when(section != Section::Done, |this| this.child(send))
                        .child(menu),
                )
            });
        gpui_kit::TestSupportExt::test_support(row).into_any_element()
    }

    fn render_open(&self, name: &str, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let (Some(story), Some(open)) = (self.story(name), self.open.as_ref()) else {
            return div().into_any_element();
        };
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let name = story.name.clone();
        let agent = crate::agent::of_project(Some(&self.project_dir));
        let (height, _) = open.fit.heights(&open.prompt, window, cx);
        let prompt = div()
            .relative()
            .w_full()
            .child(Editor::new(&open.prompt).h(height))
            .child(GrowToFit::tracker(
                &open.prompt,
                cx.entity().downgrade(),
                |this: &mut Self| &mut this.open.as_mut().expect("a story is open").fit,
            ))
            .child(open.completion.clone());
        // Its steps, numbered from 2, the one the agent added highlighted.
        let steps = story
            .steps()
            .iter()
            .enumerate()
            .map(|(at, step)| {
                let name = name.clone();
                let highlighted = open.highlight == Some(at);
                h_flex()
                    .id(SharedString::from(format!("planning-step-{name}-{at}")))
                    .gap_2()
                    .px_2()
                    .min_h(px(28.))
                    .items_center()
                    .rounded(px(4.))
                    .when(highlighted, |row| row.bg(theme.primary.opacity(0.12)))
                    .child(div().text_xs().text_color(muted).child(format!("{}", at + 2)))
                    .child(mode_pill_label(step.mode, cx))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .child(step.prompt.lines().next().unwrap_or_default().to_string()),
                    )
                    .when(highlighted, |row| {
                        row.child(
                            div()
                                .text_xs()
                                .text_color(theme.primary)
                                .child("Added by agent"),
                        )
                    })
                    .child(
                        Button::new(SharedString::from(format!("planning-step-remove-{name}-{at}")))
                            .ghost()
                            .xsmall()
                            .icon(IconName::X)
                            .tooltip(format!("Remove step {}", at + 2))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.change(
                                    &name,
                                    |anchor| {
                                        if at < anchor.added_steps.len() {
                                            anchor.added_steps.remove(at);
                                        }
                                    },
                                    cx,
                                )
                            })),
                    )
            })
            .collect::<Vec<_>>();
        let attachments = {
            let mut items: Vec<(String, usize, u8)> = Vec::new();
            for (ix, text) in story.anchor.attached_text.iter().enumerate() {
                let first = text.lines().next().unwrap_or_default();
                items.push((format!("Text: {first}"), ix, 0));
            }
            for (ix, path) in story.anchor.attached_images.iter().enumerate() {
                items.push((file_name(path), ix, 1));
            }
            for (ix, path) in story.anchor.attached_files.iter().enumerate() {
                items.push((file_name(path), ix, 2));
            }
            h_flex()
                .flex_wrap()
                .gap_1()
                .children(items.into_iter().map(|(label, ix, kind)| {
                    let name = name.clone();
                    h_flex()
                        .gap_1()
                        .pl_2()
                        .rounded(px(4.))
                        .bg(theme.secondary)
                        .text_xs()
                        .child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                        .child(div().max_w(px(220.)).truncate().child(label.clone()))
                        .child(
                            Button::new(SharedString::from(format!(
                                "planning-detach-{name}-{kind}-{ix}"
                            )))
                            .ghost()
                            .xsmall()
                            .icon(IconName::X)
                            .tooltip(format!("Remove {label}"))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.change(
                                    &name,
                                    |anchor| match kind {
                                        0 => {
                                            anchor.attached_text.remove(ix);
                                        }
                                        1 => {
                                            anchor.attached_images.remove(ix);
                                        }
                                        _ => {
                                            anchor.attached_files.remove(ix);
                                        }
                                    },
                                    cx,
                                )
                            })),
                        )
                }))
                .child({
                    let name = name.clone();
                    Button::new(SharedString::from(format!("planning-attach-{name}")))
                        .ghost()
                        .xsmall()
                        .icon(IconName::Paperclip)
                        .label("Attach")
                        .tooltip("Attach files to this story")
                        .on_click(
                            cx.listener(move |this, _, window, cx| this.attach(&name, window, cx)),
                        )
                })
        };
        // Its parameters, as the chat input shows them.
        let this = cx.entity().downgrade();
        let model = story.anchor.model.clone();
        let model_picker = {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-model-{name}")))
                .ghost()
                .xsmall()
                .label(crate::models::label(agent, model.as_deref()))
                .tooltip("The model it is sent to")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        crate::models::available(agent)
                            .into_iter()
                            .map(|model| (Some(model.id), model.label)),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == model;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.model = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        };
        let efforts = crate::effort::available(agent);
        let effort = story.anchor.effort.clone();
        let effort_picker = (!efforts.is_empty()).then(|| {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-effort-{name}")))
                .ghost()
                .xsmall()
                .label(crate::effort::label(agent, effort.as_deref()))
                .tooltip("The reasoning effort it is sent with")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        efforts
                            .iter()
                            .map(|effort| (Some(effort.id.clone()), effort.label.clone())),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == effort;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.effort = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        });
        let sliced = story.anchor.sliced;
        let slice = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-slice-{name}")))
                .ghost()
                .xsmall()
                .when(sliced, |button| button.icon(IconName::Check))
                .label("Slice")
                .tooltip("Send the slice of each spec it references, rather than links to them")
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.change(&name, |anchor| anchor.sliced = !anchor.sliced, cx)
                }))
        };
        let ask_agent = (story.task.is_none()).then(|| {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-ask-agent-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Sparkles)
                .label("Ask agent")
                .tooltip("Have the agent propose what this story still needs")
                .on_click(cx.listener(move |this, _, window, cx| this.ask_agent(&name, window, cx)))
        });
        let label = |text: &'static str| div().text_xs().text_color(muted).child(text);
        let editor = v_flex()
            .id(SharedString::from(format!("planning-open-{name}")))
            .w_full()
            .gap_2()
            .p_3()
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(label("Title"))
            .child(Input::new(&open.title))
            .child(label("Prompt"))
            .child(prompt)
            .when(!steps.is_empty(), |editor| {
                editor.child(label("Steps")).child(v_flex().gap(ROW_GAP).children(steps))
            })
            .child(attachments)
            .child(
                h_flex()
                    .gap_1()
                    .items_center()
                    .child(model_picker)
                    .children(effort_picker)
                    .child(slice)
                    .child(div().flex_1())
                    .children(ask_agent),
            );
        gpui_kit::TestSupportExt::test_support(editor).into_any_element()
    }

    /// A proposal's card: where it goes, its title, mode, and prompt, and
    /// Accept, Edit, and Reject; edited in place while Edit has it open.
    fn render_proposal(
        &mut self,
        proposal: &Proposal,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let id = proposal.id.clone();
        let focus = self.row_focus(&id, cx);
        let focused = focus.is_focused(window);
        let target = proposal.target.as_deref().and_then(|name| self.story(name));
        let (label, label_color) = match target {
            Some(story) => (
                format!("Add to {}", story.title),
                chat_input::mode_color(story.mode(), cx),
            ),
            None => ("New story".to_string(), theme.accent),
        };
        let editing = self.editing.as_ref().filter(|editor| editor.id == id);
        let read_more = self.read_more.contains(&id);
        let (shown, cut) = if read_more {
            (proposal.prompt.clone(), false)
        } else {
            clipped(&proposal.prompt, PROPOSAL_LINES)
        };
        let refused = self.refused.get(&id).cloned();
        let accept = {
            let id = id.clone();
            Button::new(SharedString::from(format!("planning-accept-{id}")))
                .primary()
                .xsmall()
                .icon(IconName::Check)
                .label("Accept")
                .tooltip("Record it in the plan (A)")
                .on_click(cx.listener(move |this, _, window, cx| {
                    if this.accept(&id, cx).is_ok() {
                        this.focus_after_decision(&id, window, cx);
                    }
                }))
        };
        let edit = {
            let id = id.clone();
            Button::new(SharedString::from(format!("planning-edit-{id}")))
                .ghost()
                .xsmall()
                .icon(IconName::Pencil)
                .label(if editing.is_some() { "Done" } else { "Edit" })
                .tooltip("Change it before it is accepted (E)")
                .on_click(cx.listener(move |this, _, window, cx| {
                    if this.editing.as_ref().is_some_and(|editor| editor.id == id) {
                        this.editing = None;
                        this.focus_row(&id, window, cx);
                    } else {
                        this.edit_proposal(&id, window, cx);
                    }
                }))
        };
        let reject = {
            let id = id.clone();
            Button::new(SharedString::from(format!("planning-reject-{id}")))
                .ghost()
                .xsmall()
                .icon(IconName::X)
                .label("Reject")
                .tooltip("Let it go (R)")
                .on_click(cx.listener(move |this, _, window, cx| {
                    this.focus_after_decision(&id, window, cx);
                    this.reject(&id, cx);
                }))
        };
        let card = v_flex()
            .id(SharedString::from(format!("planning-proposal-{id}")))
            .key_context(PROPOSAL_CONTEXT)
            .track_focus(&focus)
            .aria_label(format!("Proposal: {}", proposal.story_title()))
            .w_full()
            .gap_1()
            .p_2()
            .rounded(theme.radius)
            .border_1()
            .border_color(if focused { theme.ring } else { theme.border })
            .bg(theme.background)
            .on_action(
                cx.listener(|this, _: &PreviousRow, window, cx| this.step_rows(-1, window, cx)),
            )
            .on_action(cx.listener(|this, _: &NextRow, window, cx| this.step_rows(1, window, cx)))
            .on_action(cx.listener({
                let id = id.clone();
                move |this, _: &AcceptProposal, window, cx| {
                    if this.accept(&id, cx).is_ok() {
                        this.focus_after_decision(&id, window, cx);
                    }
                }
            }))
            .on_action(cx.listener({
                let id = id.clone();
                move |this, _: &EditProposal, window, cx| this.edit_proposal(&id, window, cx)
            }))
            .on_action(cx.listener({
                let id = id.clone();
                move |this, _: &RejectProposal, window, cx| {
                    this.focus_after_decision(&id, window, cx);
                    this.reject(&id, cx);
                }
            }))
            .child(
                div()
                    .text_xs()
                    .font_medium()
                    .text_color(label_color)
                    .child(label),
            )
            .children(
                proposal
                    .note
                    .clone()
                    .map(|note| div().text_xs().text_color(muted).child(note)),
            )
            .child(
                h_flex()
                    .gap_2()
                    .items_center()
                    .child(mode_pill_label(proposal.mode(), cx))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .font_medium()
                            .child(proposal.story_title()),
                    ),
            )
            .when(editing.is_none(), |card| {
                card.child(
                    div()
                        .text_sm()
                        .text_color(theme.foreground)
                        .whitespace_normal()
                        .child(shown),
                )
                .when(cut || read_more, |card| {
                    let id = id.clone();
                    card.child(
                        Button::new(SharedString::from(format!("planning-read-more-{id}")))
                            .ghost()
                            .xsmall()
                            .label(if read_more { "Show less" } else { "Read more" })
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if !this.read_more.remove(&id) {
                                    this.read_more.insert(id.clone());
                                }
                                cx.notify();
                            })),
                    )
                })
            })
            .children(refused.map(|why| div().text_xs().text_color(theme.danger).child(why)))
            .child(
                h_flex()
                    .gap_1()
                    .justify_end()
                    .child(accept)
                    .child(edit)
                    .child(reject),
            );
        // The editor beside the card rather than in it, so typing never
        // reaches the card's own keys.
        let editor = editing.map(|editor| {
            let (title, prompt) = (editor.title.clone(), editor.prompt.clone());
            let this = cx.entity().downgrade();
            let mode = proposal.mode();
            let mode_picker = {
                let (this, id) = (this.clone(), id.clone());
                Button::new(SharedString::from(format!("planning-proposal-mode-{id}")))
                    .ghost()
                    .xsmall()
                    .child(mode_pill_label(mode, cx))
                    .tooltip("How it will be sent")
                    .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                        for choice in SendMode::ALL {
                            let (this, id) = (this.clone(), id.clone());
                            menu = menu.item(
                                PopupMenuItem::new(mode_label(choice))
                                    .checked(choice == mode)
                                    .on_click(move |_, _, cx| {
                                        this.update(cx, |this, cx| {
                                            this.set_proposal(
                                                &id,
                                                |proposal| proposal.mode = mode_slug(choice).into(),
                                                cx,
                                            )
                                        })
                                        .ok();
                                    }),
                            );
                        }
                        menu
                    })
            };
            let targets = self.targets(proposal.about.as_deref());
            let current = proposal.target.clone();
            let target_picker = {
                let (this, id) = (this.clone(), id.clone());
                Button::new(SharedString::from(format!("planning-proposal-target-{id}")))
                    .ghost()
                    .xsmall()
                    .label(
                        current
                            .as_deref()
                            .and_then(|name| targets.iter().find(|(target, _)| target == name))
                            .map_or("New story".to_string(), |(_, title)| format!("Add to {title}")),
                    )
                    .tooltip("Where it goes")
                    .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                        let choices = std::iter::once((None, "New story".to_string())).chain(
                            targets
                                .iter()
                                .map(|(name, title)| (Some(name.clone()), title.clone())),
                        );
                        for (target, label) in choices {
                            let (this, id) = (this.clone(), id.clone());
                            let checked = target == current;
                            menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                                move |_, _, cx| {
                                    let target = target.clone();
                                    this.update(cx, |this, cx| {
                                        this.set_proposal(&id, |proposal| proposal.target = target, cx)
                                    })
                                    .ok();
                                },
                            ));
                        }
                        menu
                    })
            };
            let label = |text: &'static str| div().text_xs().text_color(muted).child(text);
            v_flex()
                .gap_2()
                .p_2()
                .rounded(theme.radius)
                .bg(theme.background)
                .child(label("Title"))
                .child(Input::new(&title))
                .child(label("Prompt"))
                .child(Textarea::new(&prompt))
                .child(
                    h_flex()
                        .gap_1()
                        .items_center()
                        .child(mode_picker)
                        .child(target_picker),
                )
        });
        gpui_kit::TestSupportExt::test_support(
            v_flex()
                .id(SharedString::from(format!("planning-proposal-block-{id}")))
                .w_full()
                .gap_1()
                .child(gpui_kit::TestSupportExt::test_support(card))
                .children(editor),
        )
        .into_any_element()
    }

    /// The drafting panel: the request, the run while it goes, its error,
    /// the proposals, the notes of those decided, and the Undos of those
    /// rejected.
    fn render_draft_panel(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let Some(drafting) = &self.drafting else {
            return div().into_any_element();
        };
        let running = drafting.running;
        let activity = activity_of(&drafting.activity).clone();
        let error = drafting.error.clone();
        let details_open = drafting.details_open;
        let proposed_nothing = drafting.proposed_nothing;
        let input = drafting.input.clone();
        let about = drafting.about.is_some();
        let mut panel = v_flex()
            .id("planning-draft-panel")
            .w_full()
            .gap_2()
            .p_3()
            .mb(HEADING_GAP)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(div().text_xs().font_medium().child(if about {
                "What does this story need?"
            } else {
                "Describe what you want"
            }))
            .child(Textarea::new(&input).disabled(running.is_some()))
            .child(
                h_flex().gap_1().justify_end().child(
                    Button::new("planning-draft-run")
                        .primary()
                        .small()
                        .icon(IconName::Sparkles)
                        .label(if self.proposals.is_empty() {
                            "Draft"
                        } else {
                            "Draft more"
                        })
                        .disabled(running.is_some())
                        .tooltip(format!("Have the agent propose stories ({MOD}Enter)"))
                        .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                ),
            );
        // Loading: what the run is doing, where the proposals will appear.
        if let Some(started) = running {
            let elapsed = crate::subagents::format_elapsed(started.elapsed());
            panel = panel.child(gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-draft-running")
                    .gap_2()
                    .items_center()
                    .child(loading_line(format!("{activity} {elapsed}"), muted).flex_1())
                    .child(
                        Button::new("planning-draft-stop")
                            .ghost()
                            .small()
                            .icon(IconName::Square)
                            .label("Stop")
                            .tooltip("Stop the agent, proposing nothing")
                            .on_click(cx.listener(|this, _, _, cx| this.stop_draft(cx))),
                    ),
            ));
        }
        // Error: what went wrong, in plain words, its details collapsed.
        if let Some(error) = error {
            // Lets UI tests find the error; inert in normal builds.
            panel = panel.child(gpui_kit::TestSupportExt::test_support(
                v_flex()
                    .id("planning-draft-error")
                    .gap_1()
                    .child(
                        h_flex()
                            .gap_2()
                            .items_center()
                            .child(
                                div()
                                    .flex_1()
                                    .text_sm()
                                    .text_color(theme.danger)
                                    .child("The agent couldn't propose stories from that."),
                            )
                            .child(
                                Button::new("planning-draft-details")
                                    .ghost()
                                    .xsmall()
                                    .icon(if details_open {
                                        IconName::ChevronDown
                                    } else {
                                        IconName::ChevronRight
                                    })
                                    .label("Details")
                                    .tooltip(if details_open {
                                        "Hide what was reported"
                                    } else {
                                        "Show what was reported"
                                    })
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        if let Some(drafting) = &mut this.drafting {
                                            drafting.details_open = !drafting.details_open;
                                        }
                                        cx.notify();
                                    })),
                            )
                            .child(
                                Button::new("planning-draft-retry")
                                    .ghost()
                                    .xsmall()
                                    .label("Try again")
                                    .tooltip("Ask the agent again with the same request")
                                    .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                            ),
                    )
                    .when(details_open, |details| {
                        details.child(
                            div()
                                .text_xs()
                                .text_color(muted)
                                .font_family(theme.mono_font_family.clone())
                                .child(error.trim().to_string()),
                        )
                    }),
            ));
        }
        if proposed_nothing && self.proposals.is_empty() {
            panel = panel.child(empty_line(
                "Nothing was proposed. Try saying more about what you want.".into(),
                muted,
            ));
        }
        // The notes of those decided.
        for (at, decided) in self.decided.iter().enumerate() {
            let story = decided.story.clone();
            panel = panel.child(
                h_flex()
                    .id(("planning-decided", at))
                    .gap_1()
                    .text_xs()
                    .text_color(muted)
                    .child(Icon::new(IconName::Check).xsmall())
                    .child(
                        div()
                            .id(("planning-decided-link", at))
                            .cursor_pointer()
                            .underline()
                            .child(decided.text.clone())
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.open_story(&story, window, cx)
                            })),
                    ),
            );
        }
        // Each proposal, as a card, in the order given.
        let proposals = self.proposals.clone();
        let count = proposals.len();
        for proposal in &proposals {
            panel = panel.child(self.render_proposal(proposal, window, cx));
        }
        // The Undos of those rejected.
        let undos: Vec<(String, String)> = self
            .rejected
            .iter()
            .map(|rejected| (rejected.proposal.id.clone(), rejected.proposal.story_title()))
            .collect();
        for (id, title) in undos {
            panel = panel.child(
                h_flex()
                    .gap_2()
                    .items_center()
                    .text_xs()
                    .text_color(muted)
                    .child(format!("Rejected “{title}”."))
                    .child({
                        let id = id.clone();
                        Button::new(SharedString::from(format!("planning-undo-{id}")))
                            .ghost()
                            .xsmall()
                            .label("Undo")
                            .tooltip("Bring it back")
                            .on_click(cx.listener(move |this, _, _, cx| this.undo_reject(&id, cx)))
                    }),
            );
        }
        if count > 0 {
            panel = panel.child(
                h_flex()
                    .gap_1()
                    .justify_end()
                    .child(
                        Button::new("planning-reject-all")
                            .ghost()
                            .small()
                            .label("Reject all")
                            .tooltip("Let every proposal go")
                            .on_click(cx.listener(|this, _, _, cx| this.reject_all(cx))),
                    )
                    .child(
                        Button::new("planning-accept-all")
                            .primary()
                            .small()
                            .label(match count {
                                1 => "Accept 1".to_string(),
                                n => format!("Accept all {n}"),
                            })
                            .tooltip("Record every proposal in the plan, in order")
                            .on_click(cx.listener(|this, _, _, cx| this.accept_all(cx))),
                    ),
            );
        }
        gpui_kit::TestSupportExt::test_support(panel).into_any_element()
    }
}

fn file_name(path: &str) -> String {
    Path::new(path).file_name().map_or_else(
        || path.to_string(),
        |name| name.to_string_lossy().into_owned(),
    )
}

impl Render for Planning {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !cx.has_active_drag() {
            self.gap.set(None);
        }
        if let Some(open) = &mut self.open {
            open.fit.keep_cursor_in_view(&open.prompt, window, cx);
        }
        if self.any_running(cx) {
            self.keep_ticking(cx);
        }
        let next = self.render_section(Section::Next, window, cx);
        let backlog = self.render_section(Section::Backlog, window, cx);
        let done = (!self.sections[2].is_empty())
            .then(|| self.render_section(Section::Done, window, cx));
        // 24 pixels between sections, and around the column's top and sides.
        let column = v_flex()
            .w_full()
            .max_w(COLUMN_WIDTH)
            .gap_6()
            .pt_6()
            .px_6()
            .pb_6()
            .child(next)
            .child(backlog)
            .children(done);
        let planning = div()
            .id("planning")
            .key_context(CONTEXT)
            .track_focus(&self.focus)
            .size_full()
            .overflow_y_scroll()
            .bg(cx.theme().background)
            .on_action(
                cx.listener(|this, _: &NewStory, window, cx| this.new_story_here(window, cx)),
            )
            .on_action(
                cx.listener(|this, _: &SendSprint, window, cx| this.send_sprint(window, cx)),
            )
            .capture_action(cx.listener(|this, _: &Escape, window, cx| {
                if this.escape(window, cx) {
                    cx.stop_propagation();
                }
            }))
            .on_action(
                cx.listener(|this, _: &crate::main_window::Dismiss, window, cx| {
                    if !this.escape(window, cx) {
                        cx.propagate();
                    }
                }),
            )
            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
                // Enter accepts an open completion rather than adding a line;
                // in the drafting panel, Ctrl/Cmd+Enter drafts.
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                    && !action.secondary
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
                } else if action.secondary
                    && this.drafting.as_ref().is_some_and(|drafting| {
                        drafting.input.read(cx).focus_handle(cx).is_focused(window)
                    })
                {
                    cx.stop_propagation();
                    this.draft(cx);
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
                }
            }))
            .child(h_flex().w_full().justify_center().child(column));
        gpui_kit::TestSupportExt::test_support(planning)
    }
}

#[cfg(test)]
mod tests {
    use std::path::{Path, PathBuf};
    use std::rc::Rc;

    use gpui_kit::component::Root;
    use gpui_kit::test::TestWindowExt as _;
    use gpui_kit::{AnyWindowHandle, AppContext as _, Entity, SharedString, TestAppContext};

    use super::{
        Planning, PlanningHooks, Proposal, Section, SendMode, Story, draft_request, load,
        order_of, parse_proposals, parse_story_block, save_order_text, save_story,
    };
    use crate::divergence::Cancel;

    fn project(name: &str) -> PathBuf {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("target")
            .join(name);
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    type Run = fn(&Path, &str, &Cancel, &dyn Fn(String)) -> anyhow::Result<String>;

    fn hooks(draft: Run) -> PlanningHooks {
        PlanningHooks {
            state: Rc::new(|_, _| None),
            send: Rc::new(|_, _, _| {}),
            open_task: Rc::new(|_, _, _| {}),
            resume: Rc::new(|_, _, _| {}),
            draft,
            completions: Rc::new(crate::chat_input::prompt_completions),
        }
    }

    fn unused(_: &Path, _: &str, _: &Cancel, _: &dyn Fn(String)) -> anyhow::Result<String> {
        anyhow::bail!("unused")
    }

    /// Planning, alone in a window, for the project at `dir`.
    fn open_planning(
        dir: PathBuf,
        draft: Run,
        cx: &mut TestAppContext,
    ) -> (Entity<Planning>, AnyWindowHandle) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::piton_syntax::init();
            super::bind_keys(cx);
        });
        let mut planning = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| Planning::new(dir, hooks(draft), cx));
            planning = Some(view.clone());
            Root::new(view, window, cx)
        });
        (planning.unwrap(), window.into())
    }

    /// A project whose Backlog holds stories titled `titles`, in order.
    fn backlog(name: &str, titles: &[&str]) -> (PathBuf, Vec<String>) {
        let dir = project(name);
        let mut sections: [Vec<Story>; 3] = Default::default();
        for title in titles {
            let story = Story::new(title.to_string(), String::new(), SendMode::Both, &dir);
            save_story(&dir, &story.name, &story.anchor.source(&story.prompt)).unwrap();
            sections[1].push(story);
        }
        save_order_text(&dir, &order_of(&sections, &[])).unwrap();
        let names = sections[1].iter().map(|story| story.name.clone()).collect();
        (dir, names)
    }

    fn titles(
        planning: &Entity<Planning>,
        section: Section,
        cx: &mut TestAppContext,
    ) -> Vec<String> {
        planning.read_with(cx, |planning, _| {
            planning
                .stories(section)
                .iter()
                .map(|story| story.title.clone())
                .collect()
        })
    }

    /// Stories, their order, which section each is in, their marks, and
    /// the proposals waiting come back as they were saved.
    #[test]
    fn the_plan_comes_back_as_it_was_left() {
        let dir = project("planning-save-test");
        let mut sections: [Vec<Story>; 3] = Default::default();
        let mut first = Story::new("First".into(), "Do the first thing".into(), SendMode::Code, &dir);
        first.anchor.sliced = true;
        let mut second = Story::new("Second".into(), String::new(), SendMode::Ask, &dir);
        second.from_agent = true;
        let mut third = Story::new("Third".into(), "Third".into(), SendMode::Spec, &dir);
        third.task = Some("ThirdTask".into());
        for story in [&first, &second, &third] {
            save_story(&dir, &story.name, &story.anchor.source(&story.prompt)).unwrap();
        }
        sections[0].push(first);
        sections[1].push(second);
        sections[2].push(third);
        let proposal = parse_story_block("title: Later\nmode: spec\ntarget: new\n\nLater.").unwrap();
        save_order_text(&dir, &order_of(&sections, std::slice::from_ref(&proposal))).unwrap();

        let (loaded, proposals) = load(&dir);
        let titles: Vec<Vec<&str>> = loaded
            .iter()
            .map(|stories| stories.iter().map(|story| story.title.as_str()).collect())
            .collect();
        assert_eq!(titles, [["First"], ["Second"], ["Third"]]);
        assert_eq!(loaded[0][0].prompt, "Do the first thing");
        assert_eq!(loaded[0][0].mode(), SendMode::Code);
        assert!(loaded[0][0].anchor.sliced);
        assert!(loaded[1][0].from_agent);
        // A title with no prompt sends its title.
        assert_eq!(loaded[1][0].text(), "Second");
        assert_eq!(loaded[2][0].task.as_deref(), Some("ThirdTask"));
        assert_eq!(proposals, [proposal]);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Proposals are read from `suspense-story` blocks wherever they stand
    /// in a reply, each with its title, mode, target, and prompt.
    #[test]
    fn proposals_are_read_from_story_blocks() {
        let reply = "I read the queue.\n\n```suspense-story\ntitle: Add sprints\nmode: chain\ntarget: new\n\nStories can be gathered\ninto a sprint.\n```\n\nAnd:\n\n```suspense-story\ntitle: Test it\nmode: code\ntarget: Story_1\n\nCover the sprint.\n```\n";
        let proposals = parse_proposals(reply);
        assert_eq!(proposals.len(), 2);
        assert_eq!(proposals[0].title, "Add sprints");
        assert_eq!(proposals[0].mode(), SendMode::Both);
        assert_eq!(proposals[0].target, None);
        assert_eq!(proposals[0].prompt, "Stories can be gathered\ninto a sprint.");
        assert_eq!(proposals[1].mode(), SendMode::Code);
        assert_eq!(proposals[1].target.as_deref(), Some("Story_1"));
        assert!(parse_proposals("Nothing to propose.").is_empty());
    }

    #[test]
    fn the_request_lists_the_stories_and_what_is_wanted() {
        let request = draft_request(
            "A sprint board",
            &[("Story_1".into(), "Queue".into())],
            None,
        );
        assert!(request.ends_with("A sprint board"));
        assert!(request.contains("- Story_1: Queue"));
        assert!(request.contains("```suspense-story"));
    }

    /// Empty, each section says what is missing and what to do.
    #[gpui_kit::test]
    async fn empty_sections_say_what_to_do(cx: &mut TestAppContext) {
        let dir = project("planning-empty-test");
        let (_, handle) = open_planning(dir.clone(), unused, cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.find("planning-empty-next");
            window.find("planning-empty-backlog");
        })
        .unwrap();
        std::fs::remove_dir_all(&dir).ok();
    }

    /// From the keyboard: Down moves to the next row, Alt+Up moves a story
    /// up and on into Next sprint, M opens the mode picker, picked from with
    /// the arrows and Enter, and Delete asks before Enter deletes.
    #[gpui_kit::test]
    async fn stories_are_worked_from_the_keyboard(cx: &mut TestAppContext) {
        let (dir, names) = backlog("planning-keys-test", &["One", "Two", "Three"]);
        let (planning, handle) = open_planning(dir.clone(), unused, cx);
        let press = |key: &str, cx: &mut TestAppContext| {
            cx.update_window(handle, |_, window, cx| {
                window.render_frame(cx);
                window.press(key, cx);
                window.render_frame(cx);
            })
            .unwrap();
            cx.run_until_parked();
        };
        let focused = |cx: &mut TestAppContext| {
            cx.update_window(handle, |_, window, cx| planning.read(cx).focused_row(window))
                .unwrap()
        };
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            planning.update(cx, |planning, cx| planning.focus_row(&names[0], window, cx));
        })
        .unwrap();
        press("down", cx);
        assert_eq!(focused(cx).as_deref(), Some(names[1].as_str()));

        press("alt-up", cx);
        assert_eq!(titles(&planning, Section::Backlog, cx), ["Two", "One", "Three"]);
        press("alt-up", cx);
        assert_eq!(titles(&planning, Section::Next, cx), ["Two"]);
        assert_eq!(focused(cx).as_deref(), Some(names[1].as_str()));

        let mode = |cx: &mut TestAppContext| {
            planning.read_with(cx, |planning, _| planning.story(&names[1]).unwrap().mode())
        };
        let before = mode(cx);
        press("m", cx);
        cx.update_window(handle, |_, window, _| {
            window.find(SharedString::from(format!("planning-mode-menu-{}", names[1])));
        })
        .unwrap();
        press("down", cx);
        press("enter", cx);
        assert_ne!(mode(cx), before, "the mode picked wasn't set");
        assert!(planning.read_with(cx, |planning, _| planning.mode_menu.is_none()));

        press("delete", cx);
        cx.update_window(handle, |_, window, _| {
            window.find(SharedString::from(format!("planning-delete-{}", names[1])));
        })
        .unwrap();
        assert_eq!(titles(&planning, Section::Next, cx), ["Two"], "deleted unasked");
        press("enter", cx);
        assert!(titles(&planning, Section::Next, cx).is_empty());
        std::fs::remove_dir_all(&dir).ok();
    }

    /// The story the drafting test's harness is asked to add to.
    static TARGET: std::sync::Mutex<String> = std::sync::Mutex::new(String::new());

    fn two_proposals(
        _: &Path,
        request: &str,
        _: &Cancel,
        on_line: &dyn Fn(String),
    ) -> anyhow::Result<String> {
        on_line(r#"{"type":"assistant"}"#.into());
        let target = TARGET.lock().unwrap().clone();
        assert!(request.contains(&target), "the request doesn't name the stories");
        Ok(format!(
            "Here:\n\n```suspense-story\ntitle: First\nmode: code\ntarget: new\n\nDo the first\n```\n\n```suspense-story\ntitle: More\nmode: spec\ntarget: {target}\n\nDescribe more\n```\n"
        ))
    }

    /// The agent only proposes: nothing reaches the plan until accepted.
    /// Proposals are kept with the project; accepting a new story puts it at
    /// the Backlog's end from the agent, and an addition becomes a step of
    /// the story it names, marked as updated; once none is left, the panel
    /// closes.
    #[gpui_kit::test]
    async fn proposals_reach_the_plan_only_once_accepted(cx: &mut TestAppContext) {
        let (dir, names) = backlog("planning-propose-test", &["Queue"]);
        *TARGET.lock().unwrap() = names[0].clone();
        let (planning, handle) = open_planning(dir.clone(), two_proposals, cx);
        cx.update_window(handle, |_, window, cx| {
            planning.update(cx, |planning, cx| {
                planning.open_draft_panel(None, true, window, cx);
                let input = planning.drafting.as_ref().unwrap().input.clone();
                input.update(cx, |input, cx| input.set_value("Two things", window, cx));
                planning.draft(cx);
            });
        })
        .unwrap();
        cx.run_until_parked();
        let ids: Vec<String> = planning.read_with(cx, |planning, _| {
            planning.proposals.iter().map(|proposal| proposal.id.clone()).collect()
        });
        assert_eq!(ids.len(), 2);
        // Nothing written to the plan yet, only proposed, and kept.
        assert_eq!(titles(&planning, Section::Backlog, cx), ["Queue"]);
        let (saved, proposals) = load(&dir);
        assert_eq!(saved[1].len(), 1);
        assert_eq!(proposals.len(), 2);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.find(SharedString::from(format!("planning-proposal-{}", ids[0])));
            window.find("planning-accept-all");
        })
        .unwrap();

        // A accepts the focused one; the other, an addition, too.
        cx.update_window(handle, |_, window, cx| {
            planning.update(cx, |planning, cx| planning.focus_row(&ids[0], window, cx));
            window.render_frame(cx);
            window.press("a", cx);
        })
        .unwrap();
        cx.run_until_parked();
        assert_eq!(titles(&planning, Section::Backlog, cx), ["Queue", "First"]);
        planning.update(cx, |planning, cx| planning.accept(&ids[1], cx)).unwrap();
        planning.read_with(cx, |planning, _| {
            let first = &planning.stories(Section::Backlog)[1];
            assert!(first.from_agent);
            assert_eq!(first.mode(), SendMode::Code);
            let queue = &planning.stories(Section::Backlog)[0];
            assert!(queue.updated);
            assert_eq!(queue.steps().len(), 1);
            assert_eq!(queue.steps()[0].prompt, "Describe more");
            assert_eq!(queue.steps()[0].mode, SendMode::Spec);
            assert!(planning.proposals.is_empty());
            assert!(planning.drafting.is_none(), "the panel didn't close");
        });
        std::fs::remove_dir_all(&dir).ok();
    }

    /// An addition to a story gone by the time it is accepted adds nothing:
    /// the card stays, made a new story, saying why. A rejected proposal
    /// can be brought back with Undo.
    #[gpui_kit::test]
    async fn additions_to_a_story_gone_are_refused_and_rejects_undone(cx: &mut TestAppContext) {
        let dir = project("planning-refuse-test");
        let (planning, handle) = open_planning(dir.clone(), unused, cx);
        let proposal = Proposal {
            target: Some("Story_gone".into()),
            ..parse_story_block("title: More\nmode: code\n\nMore.").unwrap()
        };
        let id = proposal.id.clone();
        planning.update(cx, |planning, cx| {
            planning.proposals.push(proposal);
            assert!(planning.accept(&id, cx).is_err());
            let kept = planning.proposal(&id).unwrap();
            assert_eq!(kept.target, None);
            assert!(planning.stories(Section::Backlog).is_empty());
            planning.reject(&id, cx);
            assert!(planning.proposals.is_empty());
            planning.undo_reject(&id, cx);
            assert_eq!(planning.proposals.len(), 1);
        });
        cx.update_window(handle, |_, window, cx| window.render_frame(cx)).unwrap();
        std::fs::remove_dir_all(&dir).ok();
    }

    fn failing(_: &Path, _: &str, _: &Cancel, _: &dyn Fn(String)) -> anyhow::Result<String> {
        anyhow::bail!("the harness isn't signed in")
    }

    /// A run that fails says so, with Try again, and keeps the request.
    #[gpui_kit::test]
    async fn a_failed_draft_says_why_and_keeps_the_request(cx: &mut TestAppContext) {
        let dir = project("planning-draft-error-test");
        let (planning, handle) = open_planning(dir.clone(), failing, cx);
        cx.update_window(handle, |_, window, cx| {
            planning.update(cx, |planning, cx| {
                planning.open_draft_panel(None, true, window, cx);
                let input = planning.drafting.as_ref().unwrap().input.clone();
                input.update(cx, |input, cx| input.set_value("Something", window, cx));
                planning.draft(cx);
            });
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.find("planning-draft-error");
            window.find("planning-draft-retry");
            let drafting = planning.read(cx).drafting.as_ref().unwrap();
            assert_eq!(drafting.input.read(cx).value().as_ref(), "Something");
            assert!(drafting.error.as_deref().unwrap().contains("signed in"));
        })
        .unwrap();
        std::fs::remove_dir_all(&dir).ok();
    }
}

tool_use_result.originalFile:
//! Planning, as the PlanningScope says: a plain, quick list of the work
//! still to do, as Linear keeps issues. Each story is written as it will be
//! sent, a title, a prompt, and its mode, and the stories are gathered into
//! the next sprint and sent to the agent in order, all at once.
//!
//! The stories are kept with the project's data, in `.suspense/planning/`: a
//! file per story holding its hidden anchor as a queued prompt's is, with
//! its mode, model, effort, Slice, and attachments, and `order.json` listing
//! the Next sprint, Backlog, and Done sections and their stories in order,
//! with each story's title, whether it is a draft, and the task it was sent
//! as.
//!
//! [`Planning`] is the view, configured by [`PlanningHooks`]: what sending a
//! story does, how a sent story's task stands, and opening that task are
//! the application's, so the view knows nothing of the queue it sends to.

use std::cell::Cell;
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::sync::Mutex;
use std::time::{Duration, Instant};

use anyhow::{Context as _, Result};
use gpui_kit::assets::IconName;
use gpui_kit::component::button::{Button, ButtonVariants as _};
use gpui_kit::component::checkbox::Checkbox;
use gpui_kit::component::input::{
    CompletionProvider, Editor, EditorState, Enter, Escape, Input, InputEvent, InputState,
    MoveDown, MoveUp, Textarea, TextareaState,
};
use gpui_kit::component::menu::{DropdownMenu as _, PopupMenuItem};
use gpui_kit::component::spinner::Spinner;
use gpui_kit::component::{
    ActiveTheme as _, Disableable as _, Icon, Sizable as _, StyledExt as _, h_flex, v_flex,
};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use serde::{Deserialize, Serialize};

use crate::attached_file;
use crate::attached_image;
use crate::chat_input::{self, SendMode};
use crate::completion_menu::CompletionMenu;
use crate::growing_input::GrowToFit;
use crate::hidden_anchor::{APP_DIR, Attached, HiddenAnchor};
use crate::piton_syntax;

actions!(planning, [OpenPlanning, NewStory, SendSprint]);

// The keys of a focused row, as the PlanningScope's keyboard says.
actions!(
    planning_row,
    [
        PreviousRow,
        NextRow,
        ToggleStory,
        ToggleProposal,
        MoveStoryUp,
        MoveStoryDown,
        SendStory,
        PickMode,
        DeleteStory
    ]
);

/// The key context Planning's own shortcuts work in.
const CONTEXT: &str = "Planning";

/// The key context of a focused row.
const ROW_CONTEXT: &str = "PlanningRow";

/// The secondary modifier as a tooltip names it.
#[cfg(target_os = "macos")]
const MOD: &str = "⌘";
#[cfg(not(target_os = "macos"))]
const MOD: &str = "Ctrl+";

/// Planning's shortcuts: Ctrl+N (Cmd+N on macOS) adds a story and
/// Ctrl+Shift+Enter sends the sprint while Planning has focus; on a focused
/// row, the arrows move between rows, Alt with them moves the story, Enter
/// opens it, Space ticks a proposal, Ctrl+Enter sends it, M picks its mode,
/// and Delete deletes it once confirmed.
pub fn bind_keys(cx: &mut App) {
    let row = Some(ROW_CONTEXT);
    cx.bind_keys([
        KeyBinding::new("secondary-n", NewStory, Some(CONTEXT)),
        KeyBinding::new("secondary-shift-enter", SendSprint, Some(CONTEXT)),
        KeyBinding::new("up", PreviousRow, row),
        KeyBinding::new("down", NextRow, row),
        KeyBinding::new("enter", ToggleStory, row),
        KeyBinding::new("space", ToggleProposal, row),
        KeyBinding::new("alt-up", MoveStoryUp, row),
        KeyBinding::new("alt-down", MoveStoryDown, row),
        KeyBinding::new("secondary-enter", SendStory, row),
        KeyBinding::new("m", PickMode, row),
        KeyBinding::new("delete", DeleteStory, row),
        #[cfg(target_os = "macos")]
        KeyBinding::new("backspace", DeleteStory, row),
    ]);
}

/// Where the project's stories are kept.
const PLANNING_DIR: &str = "planning";

/// The file listing the sections and their stories.
const ORDER_FILE: &str = "order.json";

/// How wide the column of stories is, at most.
const COLUMN_WIDTH: Pixels = px(760.);

/// How tall a story's row is.
const ROW_HEIGHT: Pixels = px(36.);

/// The most rows a story's prompt grows to before it scrolls.
const PROMPT_MAX_ROWS: usize = 12;

/// The most rows the box saying what is wanted grows to.
const DRAFT_MAX_ROWS: usize = 6;

/// A section of the plan.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Section {
    Next,
    Backlog,
    Done,
    /// The stories a drafting run proposed, not yet added.
    Proposed,
}

impl Section {
    fn label(self) -> &'static str {
        match self {
            Section::Next => "Next sprint",
            Section::Backlog => "Backlog",
            Section::Done => "Done",
            Section::Proposed => "Proposed stories",
        }
    }

    /// What its empty state says: what is missing, and what to do.
    fn empty(self) -> String {
        match self {
            Section::Next => format!("Nothing planned. Drag stories here, or press {MOD}N."),
            Section::Backlog => {
                format!("Backlog is empty. Press {MOD}N to add a story, or draft some.")
            }
            Section::Done => "Nothing done yet.".into(),
            Section::Proposed => {
                "No stories were proposed. Try saying more about what you want.".into()
            }
        }
    }

    fn key(self) -> &'static str {
        match self {
            Section::Next => "next",
            Section::Backlog => "backlog",
            Section::Done => "done",
            Section::Proposed => "proposed",
        }
    }
}

/// A story's mode as its pill reads it.
pub fn mode_label(mode: SendMode) -> &'static str {
    match mode {
        SendMode::Code => "Code",
        SendMode::Both => "Chain",
        SendMode::Spec => "Spec",
        SendMode::Ask => "Ask",
        SendMode::Freeform => "Freeform",
    }
}

/// The mode a `suspense-prompt` block or a drafted story names.
fn mode_of_slug(slug: &str) -> Option<SendMode> {
    match slug.trim().to_ascii_lowercase().as_str() {
        "code" => Some(SendMode::Code),
        "chain" | "combined" | "both" => Some(SendMode::Both),
        "spec" => Some(SendMode::Spec),
        "ask" => Some(SendMode::Ask),
        "freeform" => Some(SendMode::Freeform),
        _ => None,
    }
}

/// The mode last picked for a story, which a new one takes.
static LAST_MODE: Mutex<Option<SendMode>> = Mutex::new(None);

fn last_mode() -> SendMode {
    LAST_MODE
        .lock()
        .ok()
        .and_then(|mode| *mode)
        .unwrap_or(SendMode::Both)
}

/// One piece of work, written as it will be sent.
pub struct Story {
    /// What it is known by: its hidden anchor's name, and its file's.
    pub name: String,
    pub title: String,
    /// Its prompt, as written; empty to send its title.
    pub prompt: String,
    /// Its mode, model, effort, Slice, and attachments.
    pub anchor: HiddenAnchor,
    /// Drafted by the harness and not yet opened.
    pub draft: bool,
    /// The task it was last sent as, by name.
    pub task: Option<String>,
    /// For a proposal, whether it is ticked to be added.
    pub checked: bool,
}

impl Story {
    /// A new story of `mode`, titled `title`, with the model and effort
    /// chosen now for the project's harness.
    pub fn new(title: String, prompt: String, mode: SendMode, project_dir: &Path) -> Self {
        let mut anchor = HiddenAnchor::random();
        anchor.rename(story_name());
        anchor.mode = Some(mode);
        let agent = crate::agent::of_project(Some(project_dir));
        anchor.model = crate::models::chosen(agent);
        anchor.effort = crate::effort::chosen(agent);
        Self {
            name: anchor.name().to_string(),
            title,
            prompt,
            anchor,
            draft: false,
            task: None,
            checked: true,
        }
    }

    pub fn mode(&self) -> SendMode {
        self.anchor.mode.unwrap_or(SendMode::Both)
    }

    /// What it sends: its prompt, or its title where it has none.
    pub fn text(&self) -> String {
        if self.prompt.trim().is_empty() {
            self.title.clone()
        } else {
            self.prompt.clone()
        }
    }

    /// Whether anything is attached to it.
    fn has_attachments(&self) -> bool {
        !self.anchor.attached_text.is_empty()
            || !self.anchor.attached_images.is_empty()
            || !self.anchor.attached_files.is_empty()
    }

    /// A copy of it under a new name, never sent.
    fn duplicate(&self) -> Self {
        let source = self.anchor.source(&self.prompt);
        let mut anchor = HiddenAnchor::parse(&source)
            .map(|(anchor, _)| anchor)
            .unwrap_or_else(HiddenAnchor::random);
        anchor.rename(story_name());
        Self {
            name: anchor.name().to_string(),
            title: self.title.clone(),
            prompt: self.prompt.clone(),
            anchor,
            draft: false,
            task: None,
            checked: true,
        }
    }
}

/// A fresh name for a story's anchor and file.
fn story_name() -> String {
    HiddenAnchor::random_name().replacen("Prompt_", "Story_", 1)
}

/// A story as it is sent: the name its task takes, so its status can be
/// followed, and everything it is sent with.
pub struct StorySend {
    pub name: String,
    pub text: String,
    pub mode: SendMode,
    pub attached: Attached,
    pub sliced: bool,
    pub model: Option<String>,
    pub effort: Option<String>,
}

/// How a sent story's task stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoryState {
    Queued,
    Running,
    Paused,
    Done,
    Failed,
    Cancelled,
}

impl StoryState {
    fn ended(self) -> bool {
        matches!(self, Self::Done | Self::Failed | Self::Cancelled)
    }

    fn label(self) -> &'static str {
        match self {
            Self::Queued => "Queued",
            Self::Running => "Running",
            Self::Paused => "Paused",
            Self::Done => "Done",
            Self::Failed => "Failed",
            Self::Cancelled => "Cancelled",
        }
    }
}

/// How the task named so stands, and how long it has run while it runs.
pub type StateOf = Rc<dyn Fn(&str, &App) -> Option<(StoryState, Option<Duration>)>>;

/// Sends stories, in order, as one block.
pub type SendStories = Rc<dyn Fn(Vec<StorySend>, &mut Window, &mut App)>;

/// Opens the task named so.
pub type OpenTask = Rc<dyn Fn(&str, &mut Window, &mut App)>;

/// The completions a prompt offers.
pub type Completions = Rc<dyn Fn(&App) -> Rc<dyn CompletionProvider>>;

/// What the application does for Planning.
#[derive(Clone)]
pub struct PlanningHooks {
    /// How the task named so stands; none while it can't be found, as when
    /// it is still being queued.
    pub state: StateOf,
    /// Sends the stories, in order, as one block.
    pub send: SendStories,
    /// Opens the task named so in the Tasks tab.
    pub open_task: OpenTask,
    /// Resumes the paused task named so.
    pub resume: OpenTask,
    /// Asks the harness to break what is wanted into stories, blocking;
    /// gives its reply.
    pub draft: fn(&Path, &str) -> Result<String>,
    /// The completions a story's prompt offers, as the chat input's.
    pub completions: Completions,
}

/// How many stories in Next sprint are not yet sent, for the ribbon's Send
/// Sprint: the open project's.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SprintPending(pub usize);

impl Global for SprintPending {}

impl SprintPending {
    pub fn get(cx: &App) -> usize {
        cx.try_global::<Self>().map_or(0, |pending| pending.0)
    }
}

// --- Saving -----------------------------------------------------------------

/// A story's entry in `order.json`.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
struct Entry {
    story: String,
    #[serde(default)]
    title: String,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    draft: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    task: Option<String>,
    /// For a proposal, whether it is ticked to be added.
    #[serde(default = "ticked", skip_serializing_if = "Clone::clone")]
    checked: bool,
}

fn ticked() -> bool {
    true
}

/// `order.json`: the sections and their stories, in order.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct Order {
    #[serde(default)]
    next: Vec<Entry>,
    #[serde(default)]
    backlog: Vec<Entry>,
    #[serde(default)]
    done: Vec<Entry>,
    /// The stories a drafting run proposed, kept until added or discarded.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    proposals: Vec<Entry>,
}

/// Where the project's stories are kept.
pub fn planning_dir(project_dir: &Path) -> PathBuf {
    project_dir.join(APP_DIR).join(PLANNING_DIR)
}

fn story_file(project_dir: &Path, name: &str) -> PathBuf {
    planning_dir(project_dir).join(format!("{name}.pi"))
}

/// The plan as saved: Next sprint, Backlog, Done, and the proposals, in order. A story's
/// file not listed goes at the end of the Backlog; one listed whose file is
/// gone is left out.
pub fn load(project_dir: &Path) -> [Vec<Story>; 4] {
    let dir = planning_dir(project_dir);
    let order: Order = std::fs::read_to_string(dir.join(ORDER_FILE))
        .ok()
        .and_then(|text| serde_json::from_str(&text).ok())
        .unwrap_or_default();
    let read = |entry: &Entry| -> Option<Story> {
        let source = std::fs::read_to_string(story_file(project_dir, &entry.story)).ok()?;
        let (anchor, prompt) = HiddenAnchor::parse(&source)?;
        Some(Story {
            name: entry.story.clone(),
            title: entry.title.clone(),
            prompt,
            anchor,
            draft: entry.draft,
            task: entry.task.clone(),
            checked: entry.checked,
        })
    };
    let mut listed = std::collections::HashSet::new();
    let mut sections = [order.next, order.backlog, order.done, order.proposals].map(|entries| {
        entries
            .iter()
            .filter(|entry| listed.insert(entry.story.clone()))
            .filter_map(read)
            .collect::<Vec<_>>()
    });
    let mut unlisted: Vec<PathBuf> = std::fs::read_dir(&dir)
        .map(|entries| {
            entries
                .flatten()
                .map(|entry| entry.path())
                .filter(|path| path.extension().is_some_and(|ext| ext == "pi"))
                .collect()
        })
        .unwrap_or_default();
    unlisted.sort();
    for path in unlisted {
        let Some(name) = path.file_stem().and_then(|stem| stem.to_str()) else {
            continue;
        };
        if listed.contains(name) {
            continue;
        }
        let entry = Entry {
            story: name.to_string(),
            title: String::new(),
            draft: false,
            task: None,
            checked: true,
        };
        if let Some(story) = read(&entry) {
            sections[1].push(story);
        }
    }
    sections
}

/// Saves a story's file, named `name`, holding `source`, its hidden
/// anchor's.
fn save_story(project_dir: &Path, name: &str, source: &str) -> Result<()> {
    let dir = planning_dir(project_dir);
    std::fs::create_dir_all(&dir).with_context(|| format!("could not create {}", dir.display()))?;
    let file = story_file(project_dir, name);
    std::fs::write(&file, source).with_context(|| format!("could not save {}", file.display()))
}

/// The order of `sections` as `order.json` holds it.
fn order_of(sections: &[Vec<Story>; 4]) -> String {
    let entries = |stories: &Vec<Story>| {
        stories
            .iter()
            .map(|story| Entry {
                story: story.name.clone(),
                title: story.title.clone(),
                draft: story.draft,
                task: story.task.clone(),
                checked: story.checked,
            })
            .collect()
    };
    let order = Order {
        next: entries(&sections[0]),
        backlog: entries(&sections[1]),
        done: entries(&sections[2]),
        proposals: entries(&sections[3]),
    };
    serde_json::to_string_pretty(&order).unwrap_or_default()
}

fn save_order_text(project_dir: &Path, text: &str) -> Result<()> {
    let dir = planning_dir(project_dir);
    std::fs::create_dir_all(&dir).with_context(|| format!("could not create {}", dir.display()))?;
    let file = dir.join(ORDER_FILE);
    std::fs::write(&file, text).with_context(|| format!("could not save {}", file.display()))
}

// --- Drafting -----------------------------------------------------------------

/// A story as the harness drafts it.
#[derive(Debug, PartialEq, Deserialize)]
struct Drafted {
    #[serde(default)]
    title: String,
    #[serde(default)]
    prompt: String,
    #[serde(default)]
    mode: String,
}

#[derive(Deserialize)]
struct DraftReply {
    stories: Vec<Drafted>,
}

/// The request asking the harness to break `wanted` into stories.
pub fn draft_request(wanted: &str) -> String {
    // Written in system-prompts/planning.pi.
    use crate::baked_prompts::planning;
    format!(
        "{}\n\n{}\n\n{}:\n{wanted}",
        planning::REQUEST,
        planning::REPLY,
        planning::WANTED
    )
}

/// Asks the harness to break `wanted` into stories, as `planning.pi` says,
/// in a run of its own with no session. Blocking.
#[cfg_attr(test, allow(dead_code))]
pub fn ask_for_drafts(project_dir: &Path, wanted: &str) -> Result<String> {
    crate::harness::ask_quickly(project_dir, &draft_request(wanted))
}

/// The stories a drafting reply gives: each's title, prompt, and mode, in
/// order. Chain where its mode isn't one known.
pub fn parse_drafts(reply: &str) -> Result<Vec<(String, String, SendMode)>> {
    let start = reply.find('{').context("the reply held no stories")?;
    let end = reply.rfind('}').context("the reply held no stories")?;
    let parsed: DraftReply = serde_json::from_str(&reply[start..=end])
        .context("the reply's stories couldn't be read")?;
    let stories: Vec<_> = parsed
        .stories
        .into_iter()
        .filter(|story| !story.title.trim().is_empty() || !story.prompt.trim().is_empty())
        .map(|story| {
            let title = if story.title.trim().is_empty() {
                story
                    .prompt
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .trim()
                    .to_string()
            } else {
                story.title.trim().to_string()
            };
            let mode = mode_of_slug(&story.mode).unwrap_or(SendMode::Both);
            (title, story.prompt.trim().to_string(), mode)
        })
        .collect();
    Ok(stories)
}

// --- The view -----------------------------------------------------------------

/// The story open beneath its row, and its editors.
struct OpenStory {
    name: String,
    title: Entity<InputState>,
    prompt: Entity<EditorState>,
    completion: Entity<CompletionMenu>,
    fit: GrowToFit,
    _subscriptions: Vec<Subscription>,
}

/// The drafting panel, as the PlanningScope's drafting says: the request,
/// the run while it goes, and how it ended.
struct DraftPanel {
    input: Entity<TextareaState>,
    /// While the run goes: when it started.
    running: Option<Instant>,
    /// A run that failed: what was reported.
    error: Option<String>,
    details_open: bool,
    /// The last run proposed nothing.
    proposed_nothing: bool,
    _run: Option<Task<()>>,
}

/// A story's row dragged.
#[derive(Clone)]
struct StoryDrag {
    name: String,
    title: SharedString,
    mode: SendMode,
}

impl Render for StoryDrag {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        h_flex()
            .gap_2()
            .px_3()
            .h(ROW_HEIGHT)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .shadow_md()
            .text_sm()
            .child(mode_pill_label(self.mode, cx))
            .child(self.title.clone())
    }
}

pub struct Planning {
    project_dir: PathBuf,
    /// Next sprint, Backlog, Done, and the proposals, in order.
    sections: [Vec<Story>; 4],
    open: Option<OpenStory>,
    done_expanded: bool,
    drafting: Option<DraftPanel>,
    /// The mode picker open: the story's, and the mode highlighted.
    mode_menu: Option<(String, usize)>,
    /// The story asking to be deleted.
    confirm_delete: Option<String>,
    hooks: PlanningHooks,
    focus: FocusHandle,
    /// Each row's focus, by its story's name.
    row_focus: std::collections::HashMap<String, FocusHandle>,
    /// The Done section's toggle's focus.
    done_focus: FocusHandle,
    /// While a row is dragged: the gap it would land in.
    gap: Rc<Cell<Option<(Section, usize)>>>,
    /// Ticks once a second while a story's task runs, for its time.
    _tick: Option<Task<()>>,
}

impl EventEmitter<()> for Planning {}

impl Focusable for Planning {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl Planning {
    pub fn new(project_dir: PathBuf, hooks: PlanningHooks, cx: &mut Context<Self>) -> Self {
        let sections = load(&project_dir);
        let this = Self {
            project_dir,
            sections,
            open: None,
            done_expanded: false,
            drafting: None,
            mode_menu: None,
            confirm_delete: None,
            hooks,
            focus: cx.focus_handle(),
            row_focus: Default::default(),
            done_focus: cx.focus_handle().tab_stop(true),
            gap: Rc::default(),
            _tick: None,
        };
        this.publish(cx);
        this
    }

    /// The stories of `section`.
    #[cfg(test)]
    pub fn stories(&self, section: Section) -> &[Story] {
        &self.sections[section_ix(section)]
    }

    /// How many stories wait in Next sprint to be sent, for the ribbon.
    pub fn pending(&self) -> SprintPending {
        SprintPending(self.unsent())
    }

    /// Says how many stories wait in Next sprint to be sent, for the ribbon.
    fn publish(&self, cx: &mut App) {
        cx.set_global(self.pending());
    }

    fn unsent(&self) -> usize {
        self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .count()
    }

    fn find(&self, name: &str) -> Option<(Section, usize)> {
        SECTIONS.into_iter().find_map(|section| {
            self.sections[section_ix(section)]
                .iter()
                .position(|story| story.name == name)
                .map(|ix| (section, ix))
        })
    }

    fn story(&self, name: &str) -> Option<&Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get(ix)
    }

    fn story_mut(&mut self, name: &str) -> Option<&mut Story> {
        let (section, ix) = self.find(name)?;
        self.sections[section_ix(section)].get_mut(ix)
    }

    /// Saves the order in the background.
    fn save_order(&self, cx: &mut Context<Self>) {
        let text = order_of(&self.sections);
        let dir = self.project_dir.clone();
        cx.background_spawn(async move {
            if let Err(err) = save_order_text(&dir, &text) {
                eprintln!("could not save the plan: {err:#}");
            }
        })
        .detach();
        self.publish(cx);
    }

    /// Saves the story named so in the background.
    fn save_story_named(&self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let (dir, name, source) = (
            self.project_dir.clone(),
            story.name.clone(),
            story.anchor.source(&story.prompt),
        );
        cx.background_spawn(async move {
            if let Err(err) = save_story(&dir, &name, &source) {
                eprintln!("could not save the story: {err:#}");
            }
        })
        .detach();
    }

    /// Adds a story at the end of `section`, open, its title focused, in
    /// the mode last picked.
    pub fn new_story(&mut self, section: Section, window: &mut Window, cx: &mut Context<Self>) {
        self.new_story_at(section, None, window, cx);
    }

    fn new_story_at(
        &mut self,
        section: Section,
        at: Option<usize>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let section = match section {
            Section::Next | Section::Proposed => section,
            Section::Backlog | Section::Done => Section::Backlog,
        };
        self.close_story(window, cx);
        let story = Story::new(String::new(), String::new(), last_mode(), &self.project_dir);
        let name = story.name.clone();
        let stories = &mut self.sections[section_ix(section)];
        let at = at.unwrap_or(stories.len()).min(stories.len());
        stories.insert(at, story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        self.open_story(&name, window, cx);
    }

    /// Adds a story of `mode` holding `prompt` at the end of the Backlog.
    pub fn add_story(
        &mut self,
        title: String,
        prompt: String,
        mode: SendMode,
        cx: &mut Context<Self>,
    ) {
        let story = Story::new(title, prompt, mode, &self.project_dir);
        let name = story.name.clone();
        self.sections[1].push(story);
        self.save_story_named(&name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Opens the story named so beneath its row, closing any other.
    fn open_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            return;
        }
        self.close_story(window, cx);
        // A draft opened is a story like any other; a proposal stays one
        // until it is added.
        let proposal = self
            .find(name)
            .is_some_and(|(section, _)| section == Section::Proposed);
        let Some(story) = self.story_mut(name) else {
            return;
        };
        let was_draft = !proposal && std::mem::take(&mut story.draft);
        let (title_text, prompt_text) = (story.title.clone(), story.prompt.clone());
        let title = cx.new(|cx| {
            InputState::new(window, cx)
                .placeholder("Story title")
                .default_value(title_text)
        });
        let prompt = cx.new(|cx| {
            EditorState::new(window, cx)
                .language(piton_syntax::LANGUAGE_NAME)
                .line_number(false)
                .folding(false)
                .soft_wrap(true)
                .scroll_beyond_last_line(Some(0))
                .cursor_surrounding_lines(Some(0))
                .placeholder("Prompt… (the title is sent where there's none)")
                .default_value(prompt_text)
        });
        let completion = cx.new(|cx| CompletionMenu::new(prompt.clone(), window, cx));
        let provider = (self.hooks.completions)(cx);
        completion.update(cx, |menu, cx| menu.set_provider(provider, cx));
        let story_name = name.to_string();
        let subscriptions = vec![
            cx.subscribe_in(&title, window, {
                let name = story_name.clone();
                move |this, input, event: &InputEvent, window, cx| match event {
                    InputEvent::Change => {
                        let value = input.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.title = value;
                        }
                        this.save_order(cx);
                        cx.notify();
                    }
                    InputEvent::PressEnter { .. } => this.title_entered(&name, window, cx),
                    _ => {}
                }
            }),
            cx.subscribe_in(&prompt, window, {
                let name = story_name.clone();
                move |this, editor, event: &InputEvent, window, cx| {
                    if matches!(event, InputEvent::Change) {
                        let value = editor.read(cx).value().to_string();
                        if let Some(story) = this.story_mut(&name) {
                            story.prompt = value;
                        }
                        this.save_story_named(&name, cx);
                        if let Some(open) = &this.open {
                            open.completion
                                .update(cx, |menu, cx| menu.on_edit(window, cx));
                        }
                    }
                    cx.notify();
                }
            }),
        ];
        title.update(cx, |input, cx| input.focus(window, cx));
        self.open = Some(OpenStory {
            name: story_name,
            title,
            prompt,
            completion,
            fit: GrowToFit::new(PROMPT_MAX_ROWS),
            _subscriptions: subscriptions,
        });
        if was_draft {
            self.save_order(cx);
        }
        cx.notify();
    }

    /// Closes the open story, its row focused again; one left with neither
    /// title nor prompt is removed.
    fn close_story(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(open) = self.open.take() else {
            return;
        };
        let empty = self
            .story(&open.name)
            .is_some_and(|story| story.title.trim().is_empty() && story.prompt.trim().is_empty());
        if empty {
            self.delete(&open.name, cx);
            self.focus.focus(window, cx);
        } else {
            self.focus_row(&open.name, window, cx);
        }
        cx.notify();
    }

    fn toggle_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.close_story(window, cx);
        } else {
            self.open_story(name, window, cx);
        }
    }

    /// Enter in an open story's title: it is kept, and another starts
    /// beneath it, so a list can be written down without the mouse.
    fn title_entered(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        if self.sections[section_ix(section)][ix]
            .title
            .trim()
            .is_empty()
        {
            return;
        }
        self.new_story_at(section, Some(ix + 1), window, cx);
    }

    /// Escape: closes what is open, one layer at a time: the mode picker or
    /// a confirmation, the completions, the open story, then the drafting
    /// panel. Whether there was anything to close.
    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if self.mode_menu.take().is_some() || self.confirm_delete.take().is_some() {
            cx.notify();
            return true;
        }
        if let Some(open) = &self.open {
            if open.completion.read(cx).is_open() {
                open.completion.update(cx, |menu, cx| menu.hide(cx));
                return true;
            }
            self.close_story(window, cx);
            return true;
        }
        if self
            .drafting
            .as_ref()
            .is_some_and(|draft| draft.running.is_none())
            && self.sections[3].is_empty()
        {
            self.drafting = None;
            self.focus.focus(window, cx);
            cx.notify();
            return true;
        }
        false
    }

    /// Ctrl/Cmd+N: a story in the section of the one open or focused, else
    /// the Backlog.
    fn new_story_here(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let section = self
            .open
            .as_ref()
            .map(|open| open.name.clone())
            .or_else(|| self.focused_story(window))
            .and_then(|name| self.find(&name))
            .map_or(Section::Backlog, |(section, _)| section);
        self.new_story(section, window, cx);
    }

    fn delete(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        self.sections[section_ix(section)].remove(ix);
        self.row_focus.remove(name);
        if self.open.as_ref().is_some_and(|open| open.name == name) {
            self.open = None;
        }
        if self.confirm_delete.as_deref() == Some(name) {
            self.confirm_delete = None;
        }
        let file = story_file(&self.project_dir, name);
        cx.background_spawn(async move {
            std::fs::remove_file(file).ok();
        })
        .detach();
        self.save_order(cx);
        cx.notify();
    }

    /// Asks, in its row, to delete the story named so.
    fn ask_delete(&mut self, name: &str, cx: &mut Context<Self>) {
        self.mode_menu = None;
        self.confirm_delete = Some(name.to_string());
        cx.notify();
    }

    /// Deletes the story asking to be, the focus going to the row beside.
    fn confirm_delete(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(name) = self.confirm_delete.take() else {
            return;
        };
        let next = self
            .row_after(&name, 1)
            .or_else(|| self.row_after(&name, -1));
        self.delete(&name, cx);
        match next {
            Some(next) => self.focus_row(&next, window, cx),
            None => self.focus.focus(window, cx),
        }
    }

    fn duplicate(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let copy = self.sections[section_ix(section)][ix].duplicate();
        let copy_name = copy.name.clone();
        self.sections[section_ix(section)].insert(ix + 1, copy);
        self.save_story_named(&copy_name, cx);
        self.save_order(cx);
        cx.notify();
    }

    /// Moves the story named so to place `to` of `section`, counted as the
    /// section is before it is taken out.
    fn move_story(&mut self, name: &str, section: Section, to: usize, cx: &mut Context<Self>) {
        let Some((from_section, from)) = self.find(name) else {
            return;
        };
        let to = if from_section == section && to > from {
            to - 1
        } else {
            to
        };
        let story = self.sections[section_ix(from_section)].remove(from);
        let stories = &mut self.sections[section_ix(section)];
        stories.insert(to.min(stories.len()), story);
        self.save_order(cx);
        cx.notify();
    }

    pub(crate) fn move_to(&mut self, name: &str, section: Section, cx: &mut Context<Self>) {
        let end = self.sections[section_ix(section)].len();
        self.move_story(name, section, end, cx);
    }

    /// Alt+Up or Alt+Down: the story moves one place, and past the end of
    /// its section into the next, between Next sprint and the Backlog, as
    /// dragging does; a proposal or a story done moves only among its own.
    pub(crate) fn shift_story(&mut self, name: &str, up: bool, cx: &mut Context<Self>) {
        let Some((section, ix)) = self.find(name) else {
            return;
        };
        let len = self.sections[section_ix(section)].len();
        match (section, up) {
            (_, true) if ix > 0 => self.move_story(name, section, ix - 1, cx),
            (_, false) if ix + 1 < len => self.move_story(name, section, ix + 2, cx),
            (Section::Backlog, true) => self.move_to(name, Section::Next, cx),
            (Section::Next, false) => self.move_story(name, Section::Backlog, 0, cx),
            _ => {}
        }
    }

    fn set_mode(&mut self, name: &str, mode: SendMode, cx: &mut Context<Self>) {
        if let Ok(mut last) = LAST_MODE.lock() {
            *last = Some(mode);
        }
        if let Some(story) = self.story_mut(name) {
            story.anchor.mode = Some(mode);
        }
        self.mode_menu = None;
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Opens the mode picker of the story named so, its mode highlighted.
    fn open_mode_menu(&mut self, name: &str, cx: &mut Context<Self>) {
        let Some(story) = self.story(name) else {
            return;
        };
        let at = SendMode::ALL
            .iter()
            .position(|mode| *mode == story.mode())
            .unwrap_or(0);
        self.confirm_delete = None;
        self.mode_menu = Some((name.to_string(), at));
        cx.notify();
    }

    fn change(
        &mut self,
        name: &str,
        change: impl FnOnce(&mut HiddenAnchor),
        cx: &mut Context<Self>,
    ) {
        if let Some(story) = self.story_mut(name) {
            change(&mut story.anchor);
        }
        self.save_story_named(name, cx);
        cx.notify();
    }

    /// Attaches files picked to the story named so.
    fn attach(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let picked = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: true,
            prompt: Some("Attach".into()),
        });
        let (name, project_dir) = (name.to_string(), self.project_dir.clone());
        cx.spawn_in(window, async move |this, cx| {
            let Ok(Ok(Some(paths))) = picked.await else {
                return;
            };
            let saved = cx
                .background_spawn(async move {
                    let (mut images, mut files) = (Vec::new(), Vec::new());
                    for path in paths {
                        match attached_file::load(&path) {
                            Ok(attached_file::Loaded::Image(image)) => images.push(image),
                            Ok(attached_file::Loaded::File(file)) => files.push(file),
                            Err(_) => {}
                        }
                    }
                    let images = attached_image::save_all(&images, &project_dir)?;
                    let files = attached_file::save_all(&files, &project_dir)?;
                    anyhow::Ok((images, files))
                })
                .await;
            this.update(cx, |this, cx| match saved {
                Ok((images, files)) => this.change(
                    &name,
                    |anchor| {
                        anchor.attached_images.extend(images);
                        anchor.attached_files.extend(files);
                    },
                    cx,
                ),
                Err(err) => eprintln!("could not attach the files: {err:#}"),
            })
            .ok();
        })
        .detach();
    }

    /// How the story stands, once sent, and how long its task has run while
    /// it runs.
    fn status(&self, story: &Story, cx: &App) -> Option<(StoryState, Option<Duration>)> {
        let task = story.task.as_deref()?;
        Some((self.hooks.state)(task, cx).unwrap_or((StoryState::Queued, None)))
    }

    fn state(&self, story: &Story, cx: &App) -> Option<StoryState> {
        self.status(story, cx).map(|(state, _)| state)
    }

    /// Sends the stories named so, in order, as one block.
    fn send_named(&mut self, names: &[String], window: &mut Window, cx: &mut Context<Self>) {
        let mut sends = Vec::new();
        for name in names {
            let project_dir = self.project_dir.clone();
            let Some(story) = self.story_mut(name) else {
                continue;
            };
            if story.text().trim().is_empty() {
                continue;
            }
            let task = crate::prompt_title::name_for(&project_dir, &story.title);
            story.task = Some(task.clone());
            story.draft = false;
            sends.push(StorySend {
                name: task,
                text: story.text(),
                mode: story.mode(),
                attached: story.anchor.attached(),
                sliced: story.anchor.sliced,
                model: story.anchor.model.clone(),
                effort: story.anchor.effort.clone(),
            });
        }
        if sends.is_empty() {
            return;
        }
        self.save_order(cx);
        (self.hooks.send)(sends, window, cx);
        cx.notify();
    }

    /// Sends the story named so alone; a proposal or a story done is never
    /// sent from here.
    fn send_story(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .find(name)
            .is_some_and(|(section, _)| matches!(section, Section::Proposed | Section::Done))
        {
            return;
        }
        self.send_named(&[name.to_string()], window, cx);
    }

    /// Sends every story of Next sprint not yet sent, in order, as one
    /// block.
    pub fn send_sprint(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let names: Vec<String> = self.sections[0]
            .iter()
            .filter(|story| story.task.is_none())
            .map(|story| story.name.clone())
            .collect();
        self.send_named(&names, window, cx);
    }

    /// Whether every story of the sprint was sent and has ended.
    fn sprint_ended(&self, cx: &App) -> bool {
        !self.sections[0].is_empty()
            && self.sections[0]
                .iter()
                .all(|story| self.state(story, cx).is_some_and(StoryState::ended))
    }

    /// Closes the sprint: the stories done go to Done; those that failed or
    /// were cancelled stay, to be sent again.
    fn close_sprint(&mut self, cx: &mut Context<Self>) {
        let stories = std::mem::take(&mut self.sections[0]);
        for mut story in stories {
            if self.state(&story, cx) == Some(StoryState::Done) {
                self.sections[2].push(story);
            } else {
                story.task = None;
                self.sections[0].push(story);
            }
        }
        self.save_order(cx);
        cx.notify();
    }

    fn resume(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(task) = self.story(name).and_then(|story| story.task.clone()) {
            (self.hooks.resume)(&task, window, cx);
        }
    }

    /// Opens the drafting panel beneath the Backlog's heading; focused, it
    /// takes the request.
    fn open_draft_panel(&mut self, focus: bool, window: &mut Window, cx: &mut Context<Self>) {
        if self.drafting.is_none() {
            let input = cx.new(|cx| {
                TextareaState::new(window, cx)
                    .auto_grow(2, DRAFT_MAX_ROWS)
                    .placeholder("In a sentence or a paragraph…")
            });
            self.drafting = Some(DraftPanel {
                input,
                running: None,
                error: None,
                details_open: false,
                proposed_nothing: false,
                _run: None,
            });
        }
        if focus && let Some(drafting) = &self.drafting {
            drafting
                .input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    /// Asks the harness to break what the panel's request says into
    /// stories, proposed in the panel to be added.
    fn draft(&mut self, cx: &mut Context<Self>) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        let wanted = drafting.input.read(cx).value().to_string();
        if wanted.trim().is_empty() || drafting.running.is_some() {
            return;
        }
        drafting.running = Some(Instant::now());
        drafting.error = None;
        drafting.details_open = false;
        drafting.proposed_nothing = false;
        let (project_dir, ask) = (self.project_dir.clone(), self.hooks.draft);
        let run = cx.spawn(async move |this, cx| {
            let reply = cx
                .background_spawn(async move {
                    ask(&project_dir, &wanted).and_then(|reply| parse_drafts(&reply))
                })
                .await;
            this.update(cx, |this, cx| this.drafted(reply, cx)).ok();
        });
        drafting._run = Some(run);
        cx.notify();
    }

    /// Stops the run: whatever it would have proposed is never shown.
    fn stop_draft(&mut self, cx: &mut Context<Self>) {
        if let Some(drafting) = &mut self.drafting {
            drafting._run = None;
            drafting.running = None;
        }
        cx.notify();
    }

    fn drafted(&mut self, reply: Result<Vec<(String, String, SendMode)>>, cx: &mut Context<Self>) {
        let Some(drafting) = &mut self.drafting else {
            return;
        };
        drafting.running = None;
        drafting._run = None;
        match reply {
            Ok(stories) if stories.is_empty() => drafting.proposed_nothing = true,
            Ok(stories) => {
                for (title, prompt, mode) in stories {
                    let mut story = Story::new(title, prompt, mode, &self.project_dir);
                    story.draft = true;
                    let name = story.name.clone();
                    self.sections[3].push(story);
                    self.save_story_named(&name, cx);
                }
                self.save_order(cx);
            }
            Err(err) => drafting.error = Some(format!("{err:#}")),
        }
        cx.notify();
    }

    fn toggle_proposal(&mut self, name: &str, cx: &mut Context<Self>) {
        if self
            .find(name)
            .is_some_and(|(section, _)| section == Section::Proposed)
            && let Some(story) = self.story_mut(name)
        {
            story.checked = !story.checked;
            self.save_order(cx);
            cx.notify();
        }
    }

    /// Adds the proposals ticked to the Backlog, in order, as drafts, lets
    /// the rest go, and closes the panel.
    pub(crate) fn add_proposals(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        for story in std::mem::take(&mut self.sections[3]) {
            if story.checked {
                self.sections[1].push(story);
            } else {
                std::fs::remove_file(story_file(&self.project_dir, &story.name)).ok();
            }
        }
        self.close_panel(window, cx);
    }

    /// Lets every proposal go, and closes the panel.
    fn discard_proposals(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        for story in std::mem::take(&mut self.sections[3]) {
            std::fs::remove_file(story_file(&self.project_dir, &story.name)).ok();
        }
        self.close_panel(window, cx);
    }

    fn close_panel(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .open
            .as_ref()
            .is_some_and(|open| self.find(&open.name).is_none())
        {
            self.open = None;
        }
        self.drafting = None;
        self.save_order(cx);
        self.focus.focus(window, cx);
        cx.notify();
    }

    /// The rows in the order they are shown, by their stories' names.
    fn shown_rows(&self) -> Vec<String> {
        let mut shown = vec![Section::Next];
        if self.drafting.is_some() || !self.sections[3].is_empty() {
            shown.push(Section::Proposed);
        }
        shown.push(Section::Backlog);
        if self.done_expanded {
            shown.push(Section::Done);
        }
        shown
            .into_iter()
            .flat_map(|section| self.sections[section_ix(section)].iter())
            .map(|story| story.name.clone())
            .collect()
    }

    /// The row `step` rows on from the story named so.
    fn row_after(&self, name: &str, step: isize) -> Option<String> {
        let rows = self.shown_rows();
        let at = rows.iter().position(|row| row == name)? as isize + step;
        rows.get(usize::try_from(at).ok()?).cloned()
    }

    fn row_focus(&mut self, name: &str, cx: &mut App) -> FocusHandle {
        self.row_focus
            .entry(name.to_string())
            .or_insert_with(|| cx.focus_handle().tab_stop(true))
            .clone()
    }

    fn focus_row(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        let handle = self.row_focus(name, cx);
        handle.focus(window, cx);
        cx.notify();
    }

    /// The story whose row has the focus.
    fn focused_story(&self, window: &Window) -> Option<String> {
        self.row_focus
            .iter()
            .find(|(_, handle)| handle.is_focused(window))
            .map(|(name, _)| name.clone())
    }

    /// Up or Down on a focused row: the mode picker's highlight moves while
    /// it is open, else the focus moves to the row beside.
    fn step_rows(&mut self, step: isize, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((_, at)) = &mut self.mode_menu {
            let count = SendMode::ALL.len() as isize;
            *at = (*at as isize + step).rem_euclid(count) as usize;
            cx.notify();
            return;
        }
        let Some(name) = self.focused_story(window) else {
            return;
        };
        if let Some(next) = self.row_after(&name, step) {
            self.focus_row(&next, window, cx);
        }
    }

    /// Enter on a focused row: picks the highlighted mode while the picker
    /// is open, deletes a story whose delete was asked for, else opens or
    /// closes the story.
    fn enter_row(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some((name, at)) = self.mode_menu.clone() {
            self.set_mode(&name, SendMode::ALL[at], cx);
            return;
        }
        if self.confirm_delete.is_some() {
            return self.confirm_delete(window, cx);
        }
        if let Some(name) = self.focused_story(window) {
            self.toggle_story(&name, window, cx);
        }
    }

    /// Ticks once a second while a story's task runs, so its time counts.
    fn keep_ticking(&mut self, cx: &mut Context<Self>) {
        if self._tick.is_some() {
            return;
        }
        self._tick = Some(cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor().timer(Duration::from_secs(1)).await;
                let running = this
                    .update(cx, |this, cx| {
                        let running = this.any_running(cx)
                            || this
                                .drafting
                                .as_ref()
                                .is_some_and(|drafting| drafting.running.is_some());
                        if running {
                            cx.notify();
                        } else {
                            this._tick = None;
                        }
                        running
                    })
                    .unwrap_or(false);
                if !running {
                    break;
                }
            }
        }));
    }

    fn any_running(&self, cx: &App) -> bool {
        self.sections[..3]
            .iter()
            .flatten()
            .any(|story| self.state(story, cx) == Some(StoryState::Running))
    }
}

/// Every section, in the order they are looked through.
const SECTIONS: [Section; 4] = [
    Section::Next,
    Section::Backlog,
    Section::Done,
    Section::Proposed,
];

fn section_ix(section: Section) -> usize {
    match section {
        Section::Next => 0,
        Section::Backlog => 1,
        Section::Done => 2,
        Section::Proposed => 3,
    }
}

/// How wide a row's grip is.
const GRIP_WIDTH: Pixels = px(16.);

/// How wide a row's mode pill is.
const PILL_WIDTH: Pixels = px(72.);

/// How wide a row's status and time are.
const STATUS_WIDTH: Pixels = px(96.);

/// How tall a section's heading is.
const HEADING_HEIGHT: Pixels = px(32.);

/// How far apart rows are.
const ROW_GAP: Pixels = px(2.);

/// How far a section's first row is beneath its heading.
const HEADING_GAP: Pixels = px(8.);

/// A mode's pill: its label, small, in its colour.
fn mode_pill_label(mode: SendMode, cx: &App) -> Div {
    let color = chat_input::mode_color(mode, cx);
    div()
        .flex_none()
        .px_1p5()
        .rounded(px(4.))
        .text_xs()
        .font_medium()
        .text_color(color)
        .bg(color.opacity(0.14))
        .child(mode_label(mode))
}

/// A sent story's status, as a task's is shown in the message list: its
/// coloured label, with a spinner and its time while it runs, and a pause
/// icon while paused.
fn status_label(state: StoryState, elapsed: Option<Duration>, cx: &App) -> AnyElement {
    use crate::theme::Hue;
    let hue = match state {
        StoryState::Queued => Hue::Grey,
        StoryState::Running => Hue::Amber,
        StoryState::Done => Hue::Green,
        StoryState::Failed => Hue::Red,
        StoryState::Cancelled => Hue::Orange,
        // The theme's warning colour, as a paused task's.
        StoryState::Paused => Hue::Amber,
    };
    let muted = cx.theme().muted_foreground;
    let tag = crate::theme::tag(hue, cx).text_xs().child(
        h_flex()
            .gap_1()
            .items_center()
            .when(state == StoryState::Paused, |tag| {
                tag.child(Icon::new(IconName::Pause).xsmall())
            })
            .child(state.label()),
    );
    h_flex()
        .gap_1()
        .justify_end()
        .items_center()
        .when(state == StoryState::Running, |row| {
            row.child(Spinner::new().xsmall())
        })
        .child(tag)
        .children(
            elapsed
                .filter(|_| state == StoryState::Running)
                .map(|elapsed| {
                    div()
                        .text_xs()
                        .text_color(muted)
                        .font_features(crate::subagents::tabular_figures())
                        .child(crate::subagents::format_elapsed(elapsed))
                }),
        )
        .into_any_element()
}

/// `element`, taking the clicks on what it holds for itself, so the row
/// it sits in never sees them.
fn own_clicks(element: Div) -> Div {
    element.on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
}

/// An empty state: one muted line, centred, saying what is missing and what
/// to do.
fn empty_line(text: String, muted: Hsla) -> Div {
    div()
        .w_full()
        .h(ROW_HEIGHT)
        .flex()
        .items_center()
        .justify_center()
        .text_sm()
        .text_color(muted)
        .child(text)
}

/// A loading state: a spinner and a short muted label, where the result
/// will appear.
fn loading_line(label: String, muted: Hsla) -> Div {
    h_flex()
        .h(ROW_HEIGHT)
        .px_3()
        .gap_2()
        .items_center()
        .text_sm()
        .text_color(muted)
        .child(Spinner::new().xsmall())
        .child(label)
}

impl Planning {
    fn render_heading(&self, section: Section, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let count = self.sections[section_ix(section)].len();
        let paused = self.sections[section_ix(section)]
            .iter()
            .filter(|story| self.state(story, cx) == Some(StoryState::Paused))
            .count();
        let warning = crate::theme::Hue::Amber.of(crate::theme::palette(cx));
        let mut actions: Vec<AnyElement> = Vec::new();
        match section {
            Section::Next => {
                if self.sprint_ended(cx) {
                    actions.push(
                        Button::new("planning-close-sprint")
                            .ghost()
                            .small()
                            .label("Close sprint")
                            .tooltip(
                                "Move the stories done to Done, leaving any that failed to send again",
                            )
                            .on_click(cx.listener(|this, _, _, cx| this.close_sprint(cx)))
                            .into_any_element(),
                    );
                }
                let unsent = self.unsent();
                actions.push(
                    Button::new("planning-send-sprint")
                        .primary()
                        .small()
                        .icon(IconName::Send)
                        .label("Send sprint")
                        .disabled(unsent == 0)
                        .tooltip(match unsent {
                            0 => "Nothing in Next sprint is waiting to be sent".to_string(),
                            1 => format!("Send the one story waiting ({MOD}Shift+Enter)"),
                            n => {
                                format!("Send the {n} stories waiting, in order ({MOD}Shift+Enter)")
                            }
                        })
                        .on_click(cx.listener(|this, _, window, cx| this.send_sprint(window, cx)))
                        .into_any_element(),
                );
            }
            Section::Backlog => {
                actions.push(
                    Button::new("planning-draft-stories")
                        .ghost()
                        .small()
                        .icon(IconName::Sparkles)
                        .label("Draft stories")
                        .tooltip("Describe what you want, and have the harness propose stories")
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.open_draft_panel(true, window, cx)
                        }))
                        .into_any_element(),
                );
            }
            Section::Done | Section::Proposed => {}
        }
        let name = div().text_sm().font_semibold().child(section.label());
        let heading = if section == Section::Done {
            // Collapsed until opened, from its heading.
            gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-done-toggle")
                    .track_focus(&self.done_focus)
                    .gap_2()
                    .px_1()
                    .items_center()
                    .rounded(theme.radius)
                    .border_1()
                    .border_color(gpui_kit::transparent_black())
                    .focus(|toggle| toggle.border_color(theme.ring))
                    .cursor_pointer()
                    .text_color(muted)
                    .aria_label(if self.done_expanded {
                        "Hide the stories done"
                    } else {
                        "Show the stories done"
                    })
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .on_action(cx.listener(|this, _: &ToggleStory, _, cx| {
                        this.done_expanded = !this.done_expanded;
                        cx.notify();
                    }))
                    .key_context(ROW_CONTEXT)
                    .child(
                        Icon::new(if self.done_expanded {
                            IconName::ChevronDown
                        } else {
                            IconName::ChevronRight
                        })
                        .xsmall(),
                    )
                    .child(name),
            )
            .into_any_element()
        } else {
            name.into_any_element()
        };
        h_flex()
            .w_full()
            .h(HEADING_HEIGHT)
            .flex_none()
            .gap_2()
            .items_center()
            .child(heading)
            .child(div().text_xs().text_color(muted).child(count.to_string()))
            .when(paused > 0, |row| {
                row.child(
                    div()
                        .text_xs()
                        .text_color(warning)
                        .child(format!("{paused} paused")),
                )
            })
            .child(div().flex_1())
            .children(actions)
            .into_any_element()
    }

    fn render_section(
        &mut self,
        section: Section,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let heading = self.render_heading(section, cx);
        let mut column = v_flex()
            .w_full()
            .gap(ROW_GAP)
            .child(div().pb(HEADING_GAP - ROW_GAP).child(heading));
        if section == Section::Backlog && (self.drafting.is_some() || !self.sections[3].is_empty())
        {
            // Proposals kept from before come back in their panel.
            if self.drafting.is_none() {
                self.open_draft_panel(false, window, cx);
            }
            column = column.child(self.render_draft_panel(window, cx));
        }
        if section == Section::Done && !self.done_expanded {
            return column.into_any_element();
        }
        let gap = self.gap.get();
        let count = self.sections[section_ix(section)].len();
        if count == 0 {
            // Lets UI tests find the empty state; inert in normal builds.
            column = column.child(gpui_kit::TestSupportExt::test_support(
                self.drop_zone(
                    section,
                    0,
                    div().id(SharedString::from(format!(
                        "planning-empty-{}",
                        section.key()
                    ))),
                    cx,
                )
                .child(empty_line(section.empty(), muted)),
            ));
        }
        for ix in 0..count {
            let name = self.sections[section_ix(section)][ix].name.clone();
            let open = self.open.as_ref().is_some_and(|open| open.name == name);
            let row = self.render_row(section, ix, open, gap, window, cx);
            column = column.child(row);
            if open {
                column = column.child(self.render_open(&name, window, cx));
            }
        }
        if !matches!(section, Section::Done | Section::Proposed) {
            let new_story = self
                .drop_zone(
                    section,
                    count,
                    h_flex()
                        .id(SharedString::from(format!(
                            "planning-new-story-{}",
                            section.key()
                        )))
                        .h(px(28.))
                        .px_3()
                        .gap_2()
                        .items_center()
                        .rounded(theme.radius)
                        .cursor_pointer()
                        .text_sm()
                        .text_color(muted)
                        .aria_label("New story")
                        .tooltip(move |window, cx| {
                            gpui_kit::component::tooltip::Tooltip::new(format!(
                                "Add a story here ({MOD}N)"
                            ))
                            .build(window, cx)
                        })
                        .hover(|row| row.bg(theme.list_hover)),
                    cx,
                )
                .on_click(
                    cx.listener(move |this, _, window, cx| this.new_story(section, window, cx)),
                )
                .child(Icon::new(IconName::Plus).xsmall())
                .child("New story");
            column = column.child(gpui_kit::TestSupportExt::test_support(new_story));
        }
        column.into_any_element()
    }

    /// `element` as somewhere a dragged story can be dropped, at place `at`
    /// of `section`.
    fn drop_zone(
        &self,
        section: Section,
        at: usize,
        element: Stateful<Div>,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let gap = self.gap.clone();
        let shown = gap.get() == Some((section, at));
        element
            .relative()
            .on_drag_move(move |event: &DragMoveEvent<StoryDrag>, window, _| {
                if event.bounds.contains(&event.event.position) && gap.get() != Some((section, at))
                {
                    gap.set(Some((section, at)));
                    window.refresh();
                }
            })
            .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                this.gap.set(None);
                this.move_story(&drag.name, section, at, cx);
            }))
            .when(shown, |this| {
                this.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
    }

    fn render_mode_menu(
        &self,
        name: &str,
        mode: SendMode,
        highlighted: usize,
        cx: &mut Context<Self>,
    ) -> impl IntoElement + use<> {
        let theme = cx.theme().clone();
        let items = SendMode::ALL
            .into_iter()
            .enumerate()
            .map(|(at, choice)| {
                let name = name.to_string();
                h_flex()
                    .id(SharedString::from(format!(
                        "planning-mode-{name}-{}",
                        mode_label(choice)
                    )))
                    .px_2()
                    .h(px(26.))
                    .gap_2()
                    .items_center()
                    .rounded(theme.radius)
                    .cursor_pointer()
                    .when(at == highlighted, |item| item.bg(theme.list_active))
                    .hover(|item| item.bg(theme.list_hover))
                    .aria_label(mode_label(choice))
                    .on_click(cx.listener(move |this, _, _, cx| this.set_mode(&name, choice, cx)))
                    .child(
                        div().w(px(14.)).children(
                            (choice == mode).then(|| Icon::new(IconName::Check).xsmall()),
                        ),
                    )
                    .child(mode_pill_label(choice, cx))
            })
            .collect::<Vec<_>>();
        let menu = v_flex()
            .id(SharedString::from(format!("planning-mode-menu-{name}")))
            .mt(px(26.))
            .w(px(140.))
            .p_1()
            .rounded(theme.radius)
            .border_1()
            .border_color(theme.border)
            .bg(theme.popover)
            .shadow_md()
            .occlude()
            .on_mouse_down_out(cx.listener(|this, _, _, cx| {
                this.mode_menu = None;
                cx.notify();
            }))
            .children(items);
        deferred(
            anchored()
                .snap_to_window()
                .child(gpui_kit::TestSupportExt::test_support(menu)),
        )
        .with_priority(2)
    }

    fn render_row(
        &mut self,
        section: Section,
        ix: usize,
        open: bool,
        gap: Option<(Section, usize)>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let story = &self.sections[section_ix(section)][ix];
        let name = story.name.clone();
        let mode = story.mode();
        let status = self.status(story, cx);
        let (draft, checked, attached) = (story.draft, story.checked, story.has_attachments());
        let task = story.task.clone();
        let untitled = story.title.trim().is_empty();
        let title: SharedString = if untitled {
            "Untitled".into()
        } else {
            story.title.clone().into()
        };
        let len = self.sections[section_ix(section)].len();
        let focus = self.row_focus(&name, cx);
        let focused = focus.is_focused(window);
        let group = SharedString::from(format!("planning-row-{name}"));
        let proposal = section == Section::Proposed;
        let paused = status.is_some_and(|(state, _)| state == StoryState::Paused);
        let confirming = self.confirm_delete.as_deref() == Some(name.as_str());

        // The mode picker: its pill, and beneath it, while open, the modes.
        let mode_menu = self
            .mode_menu
            .as_ref()
            .filter(|(of, _)| *of == name)
            .map(|(_, at)| *at)
            .map(|highlighted| self.render_mode_menu(&name, mode, highlighted, cx));
        let mode_picker = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-mode-{name}")))
                .ghost()
                .xsmall()
                .child(mode_pill_label(mode, cx))
                .tooltip("How it will be sent (M)")
                .on_click(cx.listener(move |this, _, _, cx| {
                    if this.mode_menu.as_ref().is_some_and(|(of, _)| *of == name) {
                        this.mode_menu = None;
                        cx.notify();
                    } else {
                        this.open_mode_menu(&name, cx);
                    }
                }))
        };
        let send = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-send-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Send)
                .label("Send")
                .tooltip(format!("Send this story on its own ({MOD}Enter)"))
                .on_click(
                    cx.listener(move |this, _, window, cx| this.send_story(&name, window, cx)),
                )
        };
        let resume = paused.then(|| {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-resume-{name}")))
                .ghost()
                .xsmall()
                .icon(IconName::Play)
                .label("Resume")
                .tooltip("Resume this story's task where it left off")
                .on_click(cx.listener(move |this, _, window, cx| this.resume(&name, window, cx)))
        });
        let this = cx.entity().downgrade();
        let menu_name = name.clone();
        let menu = Button::new(SharedString::from(format!("planning-menu-{name}")))
            .ghost()
            .xsmall()
            .icon(IconName::Ellipsis)
            .tooltip("More")
            .dropdown_menu_with_anchor(gpui_kit::Anchor::TopRight, move |menu, _, _| {
                let item =
                    |label: &'static str, act: fn(&mut Planning, &str, &mut Context<Planning>)| {
                        let (this, name) = (this.clone(), menu_name.clone());
                        PopupMenuItem::new(label).on_click(move |_, _, cx| {
                            this.update(cx, |this, cx| act(this, &name, cx)).ok();
                        })
                    };
                let menu = match section {
                    Section::Next => menu.item(item("Move to backlog", |this, name, cx| {
                        this.move_story(name, Section::Backlog, 0, cx)
                    })),
                    Section::Backlog | Section::Done => menu
                        .item(item("Move to next sprint", |this, name, cx| {
                            this.move_to(name, Section::Next, cx)
                        })),
                    Section::Proposed => menu,
                };
                menu.item(item("Duplicate", |this, name, cx| this.duplicate(name, cx)))
                    .separator()
                    .item(item("Delete…", |this, name, cx| {
                        this.ask_delete(name, cx)
                    }))
            });
        let confirm = confirming.then(|| {
            h_flex()
                .gap_1()
                .items_center()
                .child(
                    div()
                        .text_xs()
                        .text_color(theme.danger)
                        .child("Delete this story?"),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-delete-{name}")))
                        .danger()
                        .xsmall()
                        .label("Delete")
                        .tooltip("Delete it for good (Enter)")
                        .on_click(
                            cx.listener(|this, _, window, cx| this.confirm_delete(window, cx)),
                        ),
                )
                .child(
                    Button::new(SharedString::from(format!("planning-keep-{name}")))
                        .ghost()
                        .xsmall()
                        .label("Cancel")
                        .tooltip("Keep it (Escape)")
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.confirm_delete = None;
                            cx.notify();
                        })),
                )
        });
        let checkbox = proposal.then(|| {
            let name = name.clone();
            Checkbox::new(SharedString::from(format!("planning-propose-{name}")))
                .checked(checked)
                .on_click(cx.listener(move |this, _: &bool, _, cx| this.toggle_proposal(&name, cx)))
        });

        let dragging = cx.has_active_drag();
        let drag = StoryDrag {
            name: name.clone(),
            title: title.clone(),
            mode,
        };
        let click_name = name.clone();
        let row = h_flex()
            .id(SharedString::from(format!("planning-story-{name}")))
            .key_context(ROW_CONTEXT)
            .track_focus(&focus)
            .aria_label(title.clone())
            .group(group.clone())
            .relative()
            .w_full()
            .h(ROW_HEIGHT)
            .flex_none()
            .px_3()
            .gap_2()
            .items_center()
            .rounded(theme.radius)
            // The focus ring, on the row the keys work on.
            .border_1()
            .border_color(if focused {
                theme.ring
            } else {
                gpui_kit::transparent_black()
            })
            .cursor_pointer()
            .when(open, |row| row.bg(theme.list_active))
            .when(!open, |row| row.hover(|row| row.bg(theme.list_hover)))
            .on_click(cx.listener(move |this, _, window, cx| {
                // A story sent opens its task; any other opens, or closes.
                this.focus_row(&click_name, window, cx);
                if let Some(task) = task.as_deref().filter(|_| !open) {
                    (this.hooks.open_task)(task, window, cx);
                } else {
                    this.toggle_story(&click_name, window, cx);
                }
            }))
            .on_action(
                cx.listener(|this, _: &PreviousRow, window, cx| this.step_rows(-1, window, cx)),
            )
            .on_action(cx.listener(|this, _: &NextRow, window, cx| this.step_rows(1, window, cx)))
            .on_action(cx.listener(|this, _: &ToggleStory, window, cx| this.enter_row(window, cx)))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &ToggleProposal, _, cx| this.toggle_proposal(&name, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryUp, window, cx| {
                    this.shift_story(&name, true, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &MoveStoryDown, window, cx| {
                    this.shift_story(&name, false, cx);
                    this.focus_row(&name, window, cx);
                }
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &SendStory, window, cx| this.send_story(&name, window, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &PickMode, _, cx| this.open_mode_menu(&name, cx)
            }))
            .on_action(cx.listener({
                let name = name.clone();
                move |this, _: &DeleteStory, _, cx| this.ask_delete(&name, cx)
            }))
            .when(!proposal, |row| {
                row.on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
                    .on_drag_move({
                        let gap = self.gap.clone();
                        move |event: &DragMoveEvent<StoryDrag>, window, _| {
                            let bounds = event.bounds;
                            if !bounds.contains(&event.event.position) {
                                return;
                            }
                            let at = ix + (event.event.position.y > bounds.center().y) as usize;
                            if gap.get() != Some((section, at)) {
                                gap.set(Some((section, at)));
                                window.refresh();
                            }
                        }
                    })
                    .on_drop(cx.listener(move |this, drag: &StoryDrag, _, cx| {
                        let at = this.gap.take().map_or(ix, |(_, at)| at);
                        this.move_story(&drag.name, section, at, cx);
                    }))
            })
            .when(dragging && gap == Some((section, ix)), |row| {
                row.child(crate::prompt_mode::drop_indicator(false, false, cx))
            })
            .when(
                dragging && gap == Some((section, ix + 1)) && ix + 1 == len,
                |row| row.child(crate::prompt_mode::drop_indicator(false, true, cx)),
            )
            // The grip, or a proposal's checkbox, in its column.
            .child(
                own_clicks(div().w(GRIP_WIDTH).flex_none().flex().justify_center())
                    .when_some(checkbox, |column, checkbox| column.child(checkbox))
                    .when(!proposal, |column| {
                        column.child(
                            Icon::new(IconName::GripVertical)
                                .xsmall()
                                .text_color(muted)
                                .cursor_grab(),
                        )
                    }),
            )
            // The mode pill, in its column, taking its own clicks.
            .child(
                own_clicks(div().relative().w(PILL_WIDTH).flex_none())
                    .child(mode_picker)
                    .children(mode_menu),
            )
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap_2()
                    .items_center()
                    .when(draft, |title| {
                        title.child(
                            div()
                                .flex_none()
                                .size(px(6.))
                                .rounded_full()
                                .bg(theme.primary),
                        )
                    })
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .text_color(if untitled { muted } else { theme.foreground })
                            .child(title),
                    )
                    .when(attached, |title| {
                        title.child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                    }),
            )
            // The status and time, right-aligned in a column of their own;
            // nothing for a story not yet sent.
            .child(
                div()
                    .w(STATUS_WIDTH)
                    .flex_none()
                    .flex()
                    .justify_end()
                    .children(status.map(|(state, elapsed)| status_label(state, elapsed, cx))),
            )
            .children(confirm.map(|confirm| own_clicks(div().flex_none()).child(confirm)))
            .children(resume.map(|resume| own_clicks(div().flex_none()).child(resume)))
            .when(!confirming, |row| {
                row.child(
                    own_clicks(h_flex())
                        .flex_none()
                        .gap_0p5()
                        .when(!focused, |buttons| {
                            buttons
                                .invisible()
                                .group_hover(group, |this| this.visible())
                        })
                        .when(
                            !matches!(section, Section::Done | Section::Proposed),
                            |this| this.child(send),
                        )
                        .child(menu),
                )
            });
        gpui_kit::TestSupportExt::test_support(row).into_any_element()
    }

    fn render_open(&self, name: &str, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let (Some(story), Some(open)) = (self.story(name), self.open.as_ref()) else {
            return div().into_any_element();
        };
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let name = story.name.clone();
        let agent = crate::agent::of_project(Some(&self.project_dir));
        let (height, _) = open.fit.heights(&open.prompt, window, cx);
        let prompt = div()
            .relative()
            .w_full()
            .child(Editor::new(&open.prompt).h(height))
            .child(GrowToFit::tracker(
                &open.prompt,
                cx.entity().downgrade(),
                |this: &mut Self| &mut this.open.as_mut().expect("a story is open").fit,
            ))
            .child(open.completion.clone());
        let attachments = {
            let mut items: Vec<(String, usize, u8)> = Vec::new();
            for (ix, text) in story.anchor.attached_text.iter().enumerate() {
                let first = text.lines().next().unwrap_or_default();
                items.push((format!("Text: {first}"), ix, 0));
            }
            for (ix, path) in story.anchor.attached_images.iter().enumerate() {
                items.push((file_name(path), ix, 1));
            }
            for (ix, path) in story.anchor.attached_files.iter().enumerate() {
                items.push((file_name(path), ix, 2));
            }
            h_flex()
                .flex_wrap()
                .gap_1()
                .children(items.into_iter().map(|(label, ix, kind)| {
                    let name = name.clone();
                    h_flex()
                        .gap_1()
                        .pl_2()
                        .rounded(px(4.))
                        .bg(theme.secondary)
                        .text_xs()
                        .child(Icon::new(IconName::Paperclip).xsmall().text_color(muted))
                        .child(div().max_w(px(220.)).truncate().child(label.clone()))
                        .child(
                            Button::new(SharedString::from(format!(
                                "planning-detach-{name}-{kind}-{ix}"
                            )))
                            .ghost()
                            .xsmall()
                            .icon(IconName::X)
                            .tooltip(format!("Remove {label}"))
                            .on_click(cx.listener(
                                move |this, _, _, cx| {
                                    this.change(
                                        &name,
                                        |anchor| match kind {
                                            0 => {
                                                anchor.attached_text.remove(ix);
                                            }
                                            1 => {
                                                anchor.attached_images.remove(ix);
                                            }
                                            _ => {
                                                anchor.attached_files.remove(ix);
                                            }
                                        },
                                        cx,
                                    )
                                },
                            )),
                        )
                }))
                .child({
                    let name = name.clone();
                    Button::new(SharedString::from(format!("planning-attach-{name}")))
                        .ghost()
                        .xsmall()
                        .icon(IconName::Paperclip)
                        .label("Attach")
                        .tooltip("Attach files to this story")
                        .on_click(
                            cx.listener(move |this, _, window, cx| this.attach(&name, window, cx)),
                        )
                })
        };
        // Its parameters, as the chat input shows them.
        let this = cx.entity().downgrade();
        let model = story.anchor.model.clone();
        let model_picker = {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-model-{name}")))
                .ghost()
                .xsmall()
                .label(crate::models::label(agent, model.as_deref()))
                .tooltip("The model it is sent to")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        crate::models::available(agent)
                            .into_iter()
                            .map(|model| (Some(model.id), model.label)),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == model;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.model = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        };
        let efforts = crate::effort::available(agent);
        let effort = story.anchor.effort.clone();
        let effort_picker = (!efforts.is_empty()).then(|| {
            let (this, name) = (this.clone(), name.clone());
            Button::new(SharedString::from(format!("planning-effort-{name}")))
                .ghost()
                .xsmall()
                .label(crate::effort::label(agent, effort.as_deref()))
                .tooltip("The reasoning effort it is sent with")
                .dropdown_menu_with_anchor(gpui_kit::Anchor::TopLeft, move |mut menu, _, _| {
                    let choices = std::iter::once((None, "Default".to_string())).chain(
                        efforts
                            .iter()
                            .map(|effort| (Some(effort.id.clone()), effort.label.clone())),
                    );
                    for (id, label) in choices {
                        let (this, name) = (this.clone(), name.clone());
                        let checked = id == effort;
                        menu = menu.item(PopupMenuItem::new(label).checked(checked).on_click(
                            move |_, _, cx| {
                                let id = id.clone();
                                this.update(cx, |this, cx| {
                                    this.change(&name, |anchor| anchor.effort = id, cx)
                                })
                                .ok();
                            },
                        ));
                    }
                    menu
                })
        });
        let sliced = story.anchor.sliced;
        let slice = {
            let name = name.clone();
            Button::new(SharedString::from(format!("planning-slice-{name}")))
                .ghost()
                .xsmall()
                .when(sliced, |button| button.icon(IconName::Check))
                .label("Slice")
                .tooltip("Send the slice of each spec it references, rather than links to them")
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.change(&name, |anchor| anchor.sliced = !anchor.sliced, cx)
                }))
        };
        let label = |text: &'static str| div().text_xs().text_color(muted).child(text);
        let editor = v_flex()
            .id(SharedString::from(format!("planning-open-{name}")))
            .w_full()
            .gap_2()
            .p_3()
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(label("Title"))
            .child(Input::new(&open.title))
            .child(label("Prompt"))
            .child(prompt)
            .child(attachments)
            .child(
                h_flex()
                    .gap_1()
                    .items_center()
                    .child(model_picker)
                    .children(effort_picker)
                    .child(slice),
            );
        gpui_kit::TestSupportExt::test_support(editor).into_any_element()
    }

    /// The drafting panel beneath the Backlog's heading: the request, the
    /// run while it goes, its error, and the stories it proposed.
    fn render_draft_panel(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let muted = theme.muted_foreground;
        let proposals = self.sections[3].len();
        let checked = self.sections[3]
            .iter()
            .filter(|story| story.checked)
            .count();
        let Some(drafting) = &self.drafting else {
            return div().into_any_element();
        };
        let running = drafting.running;
        let error = drafting.error.clone();
        let details_open = drafting.details_open;
        let proposed_nothing = drafting.proposed_nothing;
        let input = drafting.input.clone();
        let mut panel = v_flex()
            .id("planning-draft-panel")
            .w_full()
            .gap_2()
            .p_3()
            .mb(HEADING_GAP)
            .rounded(theme.radius)
            .bg(crate::theme::color(crate::theme::palette(cx).raised))
            .child(
                div()
                    .text_xs()
                    .font_medium()
                    .child("Describe what you want"),
            )
            .child(Textarea::new(&input).disabled(running.is_some()))
            .child(
                h_flex().gap_1().justify_end().child(
                    Button::new("planning-draft-run")
                        .primary()
                        .small()
                        .icon(IconName::Sparkles)
                        .label(if proposals > 0 { "Draft more" } else { "Draft" })
                        .disabled(running.is_some())
                        .tooltip(format!("Have the harness propose stories ({MOD}Enter)"))
                        .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                ),
            );
        // Loading: what the run is doing, where the proposals will appear.
        if let Some(started) = running {
            let elapsed = crate::subagents::format_elapsed(started.elapsed());
            panel = panel.child(
                h_flex()
                    .id("planning-draft-running")
                    .gap_2()
                    .items_center()
                    .child(
                        loading_line(
                            format!("Asking the harness to break it into stories… {elapsed}"),
                            muted,
                        )
                        .flex_1(),
                    )
                    .child(
                        Button::new("planning-draft-stop")
                            .ghost()
                            .small()
                            .icon(IconName::Square)
                            .label("Stop")
                            .tooltip("Stop drafting, proposing nothing")
                            .on_click(cx.listener(|this, _, _, cx| this.stop_draft(cx))),
                    ),
            );
            self.keep_ticking(cx);
        }
        // Error: what went wrong, in plain words, its details collapsed.
        if let Some(error) = error {
            // Lets UI tests find the error; inert in normal builds.
            panel = panel.child(gpui_kit::TestSupportExt::test_support(
                v_flex()
                    .id("planning-draft-error")
                    .gap_1()
                    .child(
                        h_flex()
                            .gap_2()
                            .items_center()
                            .child(
                                div()
                                    .flex_1()
                                    .text_sm()
                                    .text_color(theme.danger)
                                    .child("The harness couldn't draft stories from that."),
                            )
                            .child(
                                Button::new("planning-draft-details")
                                    .ghost()
                                    .xsmall()
                                    .icon(if details_open {
                                        IconName::ChevronDown
                                    } else {
                                        IconName::ChevronRight
                                    })
                                    .label("Details")
                                    .tooltip(if details_open {
                                        "Hide what was reported"
                                    } else {
                                        "Show what was reported"
                                    })
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        if let Some(drafting) = &mut this.drafting {
                                            drafting.details_open = !drafting.details_open;
                                        }
                                        cx.notify();
                                    })),
                            )
                            .child(
                                Button::new("planning-draft-retry")
                                    .ghost()
                                    .xsmall()
                                    .label("Try again")
                                    .tooltip("Ask the harness again with the same request")
                                    .on_click(cx.listener(|this, _, _, cx| this.draft(cx))),
                            ),
                    )
                    .when(details_open, |details| {
                        details.child(
                            div()
                                .text_xs()
                                .text_color(muted)
                                .font_family(theme.mono_font_family.clone())
                                .child(error.trim().to_string()),
                        )
                    }),
            ));
        }
        if proposed_nothing && proposals == 0 {
            panel = panel.child(empty_line(Section::Proposed.empty(), muted));
        }
        // The proposals, each a row as a story's, ticked to be added.
        if proposals > 0 {
            let gap = self.gap.get();
            let mut list = v_flex().w_full().gap(ROW_GAP).child(
                div()
                    .text_xs()
                    .text_color(muted)
                    .child(Section::Proposed.label()),
            );
            for ix in 0..proposals {
                let name = self.sections[3][ix].name.clone();
                let open = self.open.as_ref().is_some_and(|open| open.name == name);
                list = list.child(self.render_row(Section::Proposed, ix, open, gap, window, cx));
                if open {
                    list = list.child(self.render_open(&name, window, cx));
                }
            }
            panel = panel.child(list).child(
                h_flex()
                    .gap_1()
                    .justify_end()
                    .child(
                        Button::new("planning-discard-proposals")
                            .ghost()
                            .small()
                            .label("Discard")
                            .tooltip("Let every proposed story go")
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.discard_proposals(window, cx)
                            })),
                    )
                    .child(
                        Button::new("planning-add-proposals")
                            .primary()
                            .small()
                            .label(match checked {
                                1 => "Add 1 story".to_string(),
                                n => format!("Add {n} stories"),
                            })
                            .disabled(checked == 0)
                            .tooltip("Add the ticked stories to the Backlog, in order")
                            .on_click(
                                cx.listener(|this, _, window, cx| this.add_proposals(window, cx)),
                            ),
                    ),
            );
        }
        gpui_kit::TestSupportExt::test_support(panel).into_any_element()
    }
}

fn file_name(path: &str) -> String {
    Path::new(path).file_name().map_or_else(
        || path.to_string(),
        |name| name.to_string_lossy().into_owned(),
    )
}

impl Render for Planning {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !cx.has_active_drag() {
            self.gap.set(None);
        }
        if let Some(open) = &mut self.open {
            open.fit.keep_cursor_in_view(&open.prompt, window, cx);
        }
        if self.any_running(cx) {
            self.keep_ticking(cx);
        }
        let next = self.render_section(Section::Next, window, cx);
        let backlog = self.render_section(Section::Backlog, window, cx);
        let done =
            (!self.sections[2].is_empty()).then(|| self.render_section(Section::Done, window, cx));
        // 24 pixels between sections, and around the column's top and sides.
        let column = v_flex()
            .w_full()
            .max_w(COLUMN_WIDTH)
            .gap_6()
            .pt_6()
            .px_6()
            .pb_6()
            .child(next)
            .child(backlog)
            .children(done);
        let planning = div()
            .id("planning")
            .key_context(CONTEXT)
            .track_focus(&self.focus)
            .size_full()
            .overflow_y_scroll()
            .bg(cx.theme().background)
            .on_action(
                cx.listener(|this, _: &NewStory, window, cx| this.new_story_here(window, cx)),
            )
            .on_action(cx.listener(|this, _: &SendSprint, window, cx| this.send_sprint(window, cx)))
            .capture_action(cx.listener(|this, _: &Escape, window, cx| {
                if this.escape(window, cx) {
                    cx.stop_propagation();
                }
            }))
            .on_action(
                cx.listener(|this, _: &crate::main_window::Dismiss, window, cx| {
                    if !this.escape(window, cx) {
                        cx.propagate();
                    }
                }),
            )
            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
                // Enter accepts an open completion rather than adding a line;
                // in the drafting panel, Ctrl/Cmd+Enter drafts.
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                    && !action.secondary
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
                } else if action.secondary && this.drafting.is_some() {
                    cx.stop_propagation();
                    this.draft(cx);
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
                }
            }))
            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
                if let Some(open) = &this.open
                    && open.completion.read(cx).is_open()
                {
                    cx.stop_propagation();
                    open.completion
                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
                }
            }))
            .child(h_flex().w_full().justify_center().child(column));
        gpui_kit::TestSupportExt::test_support(planning)
    }
}

