    ready: bool,
    cx: &mut App,
) -> AnyElement {
    let theme = cx.theme().clone();
    let muted = theme.muted_foreground;
    let mode = proposal.as_ref().map_or(SendMode::Both, |proposal| proposal.mode());
    let color = chat_input::mode_color(mode, cx);
    let state = this
        .upgrade()
        .and_then(|this| this.read(cx).story_cards.get(&format!(\"{}/{card}\", key.id())).cloned());
    let label = match proposal.as_ref().and_then(|proposal| proposal.target.as_ref()) {
        Some(_) => \"Add to a story\",
        None => \"New story\",
    };
    let header = h_flex()
        .gap_1p5()
        .text_xs()
        .font_medium()
        .text_color(color)
        .child(Icon::new(IconName::ListChecks).xsmall())
        .child(label);
    let (title, prompt) = proposal
        .as_ref()
        .map(|proposal| (proposal.title.clone(), proposal.prompt.clone()))
        .unwrap_or_default();
    let button = |id: &str, action: StoryAction| {
        let (this, card, proposal) = (this.clone(), card.to_string(), proposal.clone());
        Button::new(SharedString::from(format!(\"story-card-{id}-{card}\")))
            .xsmall()
            .disabled(!ready || proposal.is_none())
            .on_click(move |_, window, cx| {
                let Some(proposal) = proposal.clone() else {
                    return;
                };
                this.update(cx, |this, cx| {
                    this.story_card_action(key, card.clone(), proposal, action, window, cx)
                })
                .ok();
            })
    };
    let foot: AnyElement = match &state {
        Some(StoryCard::Accepted(note)) => div()
            .text_xs()
            .text_color(muted)
            .child(note.clone())
            .into_any_element(),
        Some(StoryCard::Editing) => div()
            .text_xs()
            .text_color(muted)
            .child(\"Opened in Planning, to be edited there\")
            .into_any_element(),
        Some(StoryCard::Rejected(when)) if when.elapsed() < STORY_UNDO_FOR => h_flex()
            .gap_2()
            .items_center()
            .text_xs()
            .text_color(muted)
            .child(\"Rejected.\")
            .child(button(\"undo\", StoryAction::Undo).ghost().label(\"Undo\").tooltip(\"Bring it back\"))
            .into_any_element(),
        Some(StoryCard::Rejected(_)) => div()
            .text_xs()
            .text_color(muted)
